(function(A){Object.assign(A.D,{"G3682":{"l":"Ὀνήσιμος","o":2,"ar":"<f><o>Ὀνήσιμος</o>، <g>-ου, ὁ</g></f> <s><b>أُنسيمس</b>: <r v=\"Col.4.9\"></r>، <r v=\"Phlm.1.10\"></r> (اسم شائع بين العبيد).†</s>","en":"<f><o>Ὀνήσιμος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(i.e. <i>profitable</i>, &lt; <g>ὄνησις</g>, <i>profit</i>),</e> </et> <s><b>Onesimus</b>: <r v=\"Col.4.9\"></r>, <r v=\"Phlm.1.10\"></r> (a common name among slaves; v. MM, iii, xviii).†</s>"},"G3624":{"l":"οἶκος","o":114,"ar":"<f><o>οἶκος</o>، <g>-οῦ, ὁ</g>،</f> <s> <s n=\"1.\">بالمعنى الحرفي، <b>بيت</b>، <b>مسكن</b>: <r v=\"Acts.2.2\"></r> <r v=\"Acts.19.16\"></r>؛ مع المضاف إليه للملكية، <r v=\"Matt.9.6\"></r>، <r v=\"Matt.9.7\"></r>، <r v=\"Mark.2.11\"></r>، <r v=\"Luke.1.23\"></r>، وفي مواضع أخرى؛ مع المضاف إليه الوصفي، <g>ἐμπορίου</g>، <r v=\"John.2.16\"></r>؛ <g>προσευχῆς</g>، <r v=\"Matt.21.13\"></r>، وفي مواضع أخرى؛ عن المَقدِس: <g>οἶ. τ. θεοῦ</g>، عن خيمة الاجتماع، <r v=\"Matt.12.4\"></r>، وفي مواضع أخرى؛ الهيكل، <r v=\"Matt.21.13\"></r>، وفي مواضع أخرى؛ مجازيًا عن مدينة: <r v=\"Matt.23.38\"></r>، <r v=\"Luke.13.35\"></r>؛ عن الجسد، <r v=\"Matt.12.44\"></r>، <r v=\"Luke.11.24\"></r>؛ عن المسيحيين، <r v=\"1Pet.2.5\"></r>؛ <g>ἐν οἴ</g>، <b>في البيت</b>، <r v=\"Mark.2.1\"></r>، <r v=\"1Cor.11.34\"></r> <r v=\"1Cor.14.35\"></r>؛ وكذلك <g>κατ’ οἶκον</g>، <r v=\"Acts.2.46\"></r> <r v=\"Acts.5.42\"></r>؛ <g>οἱ εἰς</g> (= <g>οἱ ἐν</g>؛ انظر تحت مدخل <g>εἰς</g>) <g>τ. οἶ.</g>، <r v=\"Luke.7.10\"></r> <r v=\"Luke.15.6\"></r>؛ <g>κατ’ οἴκους</g>، <b>من بيت إلى بيت</b>، <r v=\"Acts.8.3\"></r> <r v=\"Acts.20.20\"></r>؛ <g>εἰς</g> (<g>κατ’</g>) <g>οἶκον</g>، مع المضاف إليه، <r v=\"Mark.8.3\"></r>، <r v=\"Luke.14.1\"></r>، <r v=\"Rom.16.5\"></r>، وفي مواضع أخرى.</s> <s n=\"2.\">كنايةً، <b>بيت</b>، <b>أهل البيت</b>، <b>عائلة</b>: <r v=\"Luke.10.5\"></r>، <r v=\"Acts.7.10\"></r>، <r v=\"1Cor.1.16\"></r>، <r v=\"1Tim.3.4\"></r>، <r v=\"1Tim.3.5\"></r> وفي مواضع أخرى؛ عن الكنيسة، <g>ὁ οἶ. τ. θεοῦ</g>، <r v=\"1Tim.3.15\"></r>، <r v=\"Heb.3.2\"></r>، <r v=\"1Pet.4.17\"></r>؛ عن النسل، <g>οἶ Ἰσραήλ</g> (<g>Δαυείδ</g>، <g>Ἰακώβ</g>)، <r v=\"Matt.10.6\"></r>، <r v=\"Luke.1.27\"></r>، <r v=\"Luke.1.33\"></r>، وفي مواضع أخرى (قارن <r v=\"Exod.6.14\"></r>، <r v=\"1Sam.2.30\"></r>، وفي مواضع أخرى).</s> </s>","en":"<f><o>οἶκος</o>, <g>-οῦ, ὁ</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1004\">בַּיִת</h>, also for <h n=\"H1964\">הֵיכָל</h>, <h n=\"H168\">אֹהֶל</h>, etc.;]</e> </et> <s> <s n=\"1.\">prop., <b>a house</b>, <b>dwelling</b>: <r v=\"Acts.2.2\"></r> <r v=\"Acts.19.16\"></r>; c. gen. poss., <r v=\"Matt.9.6\"></r>, <r v=\"Matt.9.7\"></r>, <r v=\"Mark.2.11\"></r>, <r v=\"Luke.1.23\"></r>, al.; c. gen. attrib., <g>ἐμπορίου</g>, <r v=\"John.2.16\"></r>; <g>προσευχῆς</g>, <r v=\"Matt.21.13\"></r>, al.; of a sanctuary (Hdt., Eur.): <g>οἶ. τ. θεοῦ</g>, of the tabernacle, <r v=\"Matt.12.4\"></r>, al.; the temple, <r v=\"Matt.21.13\"></r>, al.; metaph. of a city: <r v=\"Matt.23.38\"></r>, <r v=\"Luke.13.35\"></r>; of the body, <r v=\"Matt.12.44\"></r>, <r v=\"Luke.11.24\"></r>; of Christians, <r v=\"1Pet.2.5\"></r>; <g>ἐν οἴ</g> (M, <i>Pr.</i>, 81 f.), <b>at home</b>, <r v=\"Mark.2.1\"></r>, <r v=\"1Cor.11.34\"></r> <r v=\"1Cor.14.35\"></r>; so <g>κατ’ οἶκον</g>, <r v=\"Acts.2.46\"></r> <r v=\"Acts.5.42\"></r>; <g>οἱ εἰς</g> (= <g>οἱ ἐν</g>; v.s. <g>εἰς</g>) <g>τ. οἶ.</g>, <r v=\"Luke.7.10\"></r> <r v=\"Luke.15.6\"></r>; <g>κατ’ οἴκους</g>, <b>from house to house</b>, <r v=\"Acts.8.3\"></r> <r v=\"Acts.20.20\"></r>; <g>εἰς</g> (<g>κατ’</g>) <g>οἶκον</g>, c. gen. (Bl., § 46, 9), <r v=\"Mark.8.3\"></r>, <r v=\"Luke.14.1\"></r>, <r v=\"Rom.16.5\"></r>, al.</s> <s n=\"2.\">By meton., <b>a house</b>, <b>household</b>, <b>family</b>: <r v=\"Luke.10.5\"></r>, <r v=\"Acts.7.10\"></r>, <r v=\"1Cor.1.16\"></r>, <r v=\"1Tim.3.4\"></r>, <r v=\"1Tim.3.5\"></r> al.; of the Church, <g>ὁ οἶ. τ. θεοῦ</g>, <r v=\"1Tim.3.15\"></r>, <r v=\"Heb.3.2\"></r>, <r v=\"1Pet.4.17\"></r>; of descendants, <g>οἶ Ἰσραήλ</g> (<g>Δαυείδ</g>, <g>Ἰακώβ</g>; Bl, § 47, 9), <r v=\"Matt.10.6\"></r>, <r v=\"Luke.1.27\"></r>, <r v=\"Luke.1.33\"></r>, al. (cf. <r v=\"Exod.6.14\"></r>, <r v=\"1Sam.2.30\"></r>, al.).</s> </s> <sy><i>SYN.</i>: v.s. <g>οἰκία</g>.</sy>"},"G3685":{"l":"ὀνίνημι","o":1,"ar":"<f>** <o>ὀνίνημι</o>،</f> <s><b>ينفع</b>، <b>يفيد</b>، <b>يُعين</b>؛ الصيغة الوسطى، <b>ينتفع</b>، <b>يستفيد</b>: صيغة التمني، مع المضاف إليه، <r v=\"Phlm.1.20\"></r>.†</s>","en":"<f>** <o>ὀνίνημι</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Tob.3.8\"></r>, <r v=\"Sir.30.2\"></r>*;]</e> </et> <s><b>to profit</b>, <b>benefit</b>, <b>help</b>; mid., <b>to have profit</b>, <b>derive benefit</b>: optat. (M, <i>Pr.</i>, 195), c. gen., <r v=\"Phlm.1.20\"></r>.†</s>"},"G3609":{"l":"οἰκεῖος","o":3,"ar":"<f><o>οἰκεῖος</o>، <g>-α, -ον</g></f> <s><b>في البيت</b> أو <b>من البيت / بيتيّ</b> (عكس <g>ξένος, ἀλλότριος</g>)؛ <s n=\"(a)\">عن الأشياء؛ <g>τὰ οἰ.</g>، <b>شؤون البيت</b> أو <b>متاعه</b>؛</s> <s n=\"(b)\">عن الأشخاص، <b>من العائلة نفسها</b> أو <b>من الأقارب</b>؛ اسمًا، <g>οἱ οἰ.</g>، <b>الأقرباء / أهل البيت</b>: <r v=\"1Tim.5.8\"></r>؛ مع المضاف إليه للشخص، <b>من أهل بيت</b>: مجازيًا، <g>τ. θεοῦ</g>، <r v=\"Eph.2.19\"></r>؛ <g>τ. πίστεως</g>، <r v=\"Gal.6.10\"></r>.†</s> </s>","en":"<f><o>οἰκεῖος</o>, <g>-α, -ον</g></f> <et> <e t=\"derivation\">(&lt; <g>οἶκος</g>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H1730\">דּוֹד</h>, <h n=\"H7607\">שְׁאֵר</h>, etc.; in <r v=\"Isa.58.7\"></r>, <g>οἰ. τοῦ σπέρματος</g> for <h n=\"H1320\">בָּשָׂר</h>;]</e> </et> <s><b>in</b> or <b>of the house</b> (opp. to <g>ξένος, ἀλλότριος</g>); <s n=\"(a)\">of things; <g>τὰ οἰ.</g>, <b>household affairs</b> or <b>goods</b>;</s> <s n=\"(b)\">of persons, <b>of the same family</b> or <b>kin</b>; as subst., <g>οἱ οἰ.</g>, <b>kinsmen</b>: <r v=\"1Tim.5.8\"></r>; c. gen. pers., <b>of the family of</b>: metaph., <g>τ. θεοῦ</g>, <r v=\"Eph.2.19\"></r>; <g>τ. πίστεως</g> (Lft., in l.), <r v=\"Gal.6.10\"></r>.†</s> </s> <sy><i>SYN.</i>: <g>συγγενής</g>, <g>ἴδιος</g> (v. Cremer, 446; Deiss., <i>BS.</i>, 123).</sy>"},"G3641":{"l":"ὀλίγος","o":40,"ar":"<f><o>ὀλίγος</o>، <g>-η, -ον</g></f> <s>عن العدد والكمية والحجم، <b>قليل</b>، <b>يسير</b>، <b>صغير</b>، <b>طفيف</b>: <r v=\"Matt.9.37\"></r> <r v=\"Matt.15.34\"></r>، <r v=\"Mark.6.5\"></r> <r v=\"Mark.8.7\"></r>، <r v=\"Luke.10.2\"></r> <r v=\"Luke.12.48\"></r> (أي <g>πληγάς</g>، عكس <g>πολλάς</g>)، <r v=\"1Tim.5.23\"></r>، <r v=\"Heb.12.10\"></r>، <r v=\"Rev.3.4\"></r> <r v=\"Rev.12.12\"></r>؛ <g>οὐκ ὀ.</g>، <r v=\"Acts.12.18\"></r> <r v=\"Acts.14.28\"></r> <r v=\"Acts.15.2\"></r> (مع المضاف إليه التبعيضي) <r v=\"Acts.17.4\"></r>، <r v=\"Acts.17.12\"></r> <r v=\"Acts.19.23\"></r>، <r v=\"Acts.19.24\"></r> <r v=\"Acts.27.20\"></r>؛ في الجمع، مطلقًا، <r v=\"Matt.7.14\"></r> <r v=\"Matt.20.16\"></r> <r v=\"Matt.22.14\"></r>، <r v=\"Luke.13.23\"></r>، <r v=\"1Pet.3.20\"></r>. المحايد المفرد (<g>τὸ</g>) <g>ὀ.</g>: <r v=\"Luke.7.47\"></r>، <r v=\"2Cor.8.15\"></r>؛ <g>πρὸς ὀλίγον</g>، <r v=\"1Tim.4.8\"></r>، <r v=\"Jas.4.14\"></r>؛ <g>ἐν ὀ.</g>، <r v=\"Acts.26.28\"></r>، <r v=\"Acts.26.29\"></r> (<i>بقليل</i> من الجهد)؛ وهو نفسه، <b>بإيجاز</b>، <r v=\"Eph.3.3\"></r>؛ وظرفيًا، <g>ὀλίγον</g>، عن الزمن، <r v=\"Mark.6.31\"></r>، <r v=\"1Pet.1.6\"></r> <r v=\"1Pet.5.10\"></r>، <r v=\"Rev.17.10\"></r>؛ وعن المسافة، <r v=\"Mark.1.19\"></r>، <r v=\"Luke.5.3\"></r>؛ في الجمع، <g>ὀλίγα</g>، <r v=\"Luke.10.42\"></r>، <r v=\"Rev.2.14\"></r>؛ <g>ἐπ’ ὀλίγα</g>، <r v=\"Matt.25.21\"></r>، <r v=\"Matt.25.23\"></r>؛ <g>δι’ ὀλίγων</g>، <b>بكلمات قليلة</b>، <b>باختصار</b>، <r v=\"1Pet.5.12\"></r>.†</s>","en":"<f><o>ὀλίγος</o>, <g>-η, -ον</g></f> <et> <e t=\"derivation\">(on <g>οὐχ ὁλ.</g>, v. infr.),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H4591\">מְעַט</h>;]</e> </et> <s>of number, quantity, size, <b>few</b>, <b>little</b>, <b>small</b>, <b>slight</b>: <r v=\"Matt.9.37\"></r> <r v=\"Matt.15.34\"></r>, <r v=\"Mark.6.5\"></r> <r v=\"Mark.8.7\"></r>, <r v=\"Luke.10.2\"></r> <r v=\"Luke.12.48\"></r> (sc. <g>πληγάς</g>, opp. to <g>πολλάς</g>), <r v=\"1Tim.5.23\"></r>, <r v=\"Heb.12.10\"></r>, <r v=\"Rev.3.4\"></r> <r v=\"Rev.12.12\"></r>; <g>οὐκ ὀ.</g> (in the best uncials written <g>οὐκ ὀ.</g>; v. WH, <i>App.</i>, 143; M, <i>Pr.</i>, 44; Thackeray, <i>Gr.</i>, 126 f.), <r v=\"Acts.12.18\"></r> <r v=\"Acts.14.28\"></r> <r v=\"Acts.15.2\"></r> (c. gen. part.) <r v=\"Acts.17.4\"></r>, <r v=\"Acts.17.12\"></r> <r v=\"Acts.19.23\"></r>, <r v=\"Acts.19.24\"></r> <r v=\"Acts.27.20\"></r>; pl., absol., <r v=\"Matt.7.14\"></r> <r v=\"Matt.20.16\"></r> (WH, txt., RV, om.) <r v=\"Matt.22.14\"></r>, <r v=\"Luke.13.23\"></r>, <r v=\"1Pet.3.20\"></r>. Neut. sing. (<g>τὸ</g>) <g>ὀ.</g>: <r v=\"Luke.7.47\"></r>, <r v=\"2Cor.8.15\"></r>; <g>πρὸς ὀλίγον</g>, <r v=\"1Tim.4.8\"></r>, <r v=\"Jas.4.14\"></r>; <g>ἐν ὀ.</g>, <r v=\"Acts.26.28\"></r>, <r v=\"Acts.26.29\"></r> (<i>with little</i> effort; v. Page, in l.); id., <b>in brief</b>, <r v=\"Eph.3.3\"></r>; adverbially, <g>ὀλίγον</g>, of time, <r v=\"Mark.6.31\"></r>, <r v=\"1Pet.1.6\"></r> <r v=\"1Pet.5.10\"></r>, <r v=\"Rev.17.10\"></r>; of space, <r v=\"Mark.1.19\"></r>, <r v=\"Luke.5.3\"></r>; pl., <g>ὀλίγα</g>, <r v=\"Luke.10.42\"></r>, <r v=\"Rev.2.14\"></r>; <g>ἐπ’ ὀλίγα</g>, <r v=\"Matt.25.21\"></r>, <r v=\"Matt.25.23\"></r>; <g>δι’ ὀλίγων</g>, <b>in few words</b>, <b>briefly</b>, <r v=\"1Pet.5.12\"></r> (cf. Plat., <i>Legg.</i>, vi, 778 e).†</s>"},"G3622":{"l":"οἰκονομία","o":9,"ar":"<f><o>οἰκονομία</o>، <g>-ας, ἡ</g></f> <s n=\"1.\">بالمعنى الحرفي، <b>وظيفة</b> الـ<g>οἰκονόμος</g>، <b>الوكالة</b>: <r v=\"Luke.16.2-Luke.16.4\"></r>.</s> <s n=\"2.\">(قارن <r v=\"Eph.1.10\"></r>)، عمومًا، <b>تدبير</b>، <b>إدارة</b>: <r v=\"1Cor.9.17\"></r>، <r v=\"Eph.1.10\"></r> <r v=\"Eph.3.2\"></r>، <r v=\"Eph.3.9\"></r>، <r v=\"Col.1.25\"></r>، <r v=\"1Tim.1.4\"></r>.†</s>","en":"<f><o>οἰκονομία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>οἰκονομέω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Isa.22.19\"></r>, <r v=\"Isa.22.21\"></r> (<h n=\"H4673\">מַצָּב</h>, <h n=\"H4475\">מֶמְשָׁלָה</h>)*;]</e> </et> <s n=\"1.\">prop. (Plat., Arist.), <b>the office of</b> <g>οἰκονόμος</g>, <b>stewardship</b>: <r v=\"Luke.16.2-Luke.16.4\"></r>.</s> <s n=\"2.\">In later writers (Plut., al.; v. AR on <r v=\"Eph.1.10\"></r>; MM, xviii), generally, <b>administration</b>, <b>dispensation</b>: <r v=\"1Cor.9.17\"></r>, <r v=\"Eph.1.10\"></r> <r v=\"Eph.3.2\"></r>, <r v=\"Eph.3.9\"></r>, <r v=\"Col.1.25\"></r>, <r v=\"1Tim.1.4\"></r>.†</s>"},"G3686":{"l":"ὄνομα","o":230,"ar":"<f><o>ὄνομα</o>، <g>-τος, τό</g>،</f> <s n=\"1.\">عمومًا، <b>الاسم</b> الذي يُدعى به شخص أو شيء: <r v=\"Matt.10.2\"></r>، <r v=\"Mark.3.16\"></r>، <r v=\"Luke.1.63\"></r>، <r v=\"John.18.10\"></r>، وفي مواضع أخرى؛ <g>ἄνθρωπος</g> (إلخ)، <g>ᾧ</g> (<g>οὗ</g>) <g>ὄ.</g> (<g>τ. ὄ</g>)، أي <g>ἦν</g> أو <g>ἐστίν</g>، <r v=\"Mark.14.32\"></r>، <r v=\"Luke.1.26\"></r>، <r v=\"Luke.1.27\"></r>؛ ومع الحذف نفسه، <g>καὶ τ. ὄ. αὐτοῦ</g> (<g>ὄ. αὐτῷ</g>)، <r v=\"Luke.1.5\"></r>، <r v=\"John.1.6\"></r>، وفي مواضع أخرى؛ <g>ὀνόματι</g>، يليه اسم علم في حالة الرفع، <r v=\"Matt.27.32\"></r>، <r v=\"Mark.5.22\"></r>، <r v=\"Luke.1.5\"></r>، <r v=\"Acts.5.1\"></r>، وفي مواضع أخرى؛ حالة النصب مطلقًا، <g>τοὔνομα</g> (= <g>τ. ὄνομα</g>)، <r v=\"Matt.27.57\"></r>؛ <g>ὄ. μοι</g> (أي <g>ἐστίν</g>)، <r v=\"Mark.5.9\"></r> (قارن <r v=\"Luke.8.30\"></r>)؛ <g>ἔξειν ὄ.</g>، <r v=\"Rev.9.11\"></r>؛ <g>καλεῖν</g> (<g>ἐπιτιθέναι</g>) <g>ὄ.</g>، <r v=\"Matt.1.21\"></r>، <r v=\"Mark.3.16\"></r>؛ <g>τ. ὄ. ἐν</g> (<g>τ.</g>) <g>βίβλῳ ζωῆς</g>، <r v=\"Phil.4.3\"></r>، <r v=\"Rev.13.8\"></r>، قارن <r v=\"Luke.10.20\"></r> (<g>ἐν τ. οὐρανοῖς</g>)؛ <g>ὄ. βλασφημίας</g>، <r v=\"Rev.13.1\"></r>؛ الاسم في مقابل الحقيقة، <r v=\"Rev.3.1\"></r>؛ لقبًا: <r v=\"Eph.1.21\"></r>، <r v=\"Phil.2.9\"></r>، <r v=\"Phil.2.10\"></r> .</s> <s n=\"2.\">باستعمال مشابه لما في العبرية <h n=\"H8034\">שֵׁם</h>، لكنه شائع أيضًا في اليونانية المتأخرة، عن كل ما يتضمّنه الاسم، من رتبة وسلطان وصفة، إلخ: عن العمل بسلطان شخص أو نيابةً عنه، <g>ἐν</g> (<g>εἰς</g>) <g>ὄ.</g>، مع المضاف إليه للشخص، <r v=\"Matt.10.41\"></r> <r v=\"Matt.21.9\"></r> <r v=\"Matt.28.19\"></r>، <r v=\"Mark.11.9\"></r>، <r v=\"Luke.13.35\"></r>، <r v=\"John.5.43\"></r>، <r v=\"Acts.8.16\"></r>، <r v=\"1Cor.1.13\"></r>؛ عن اسم «مسيحي»، <r v=\"1Pet.4.16\"></r>؛ خاصةً عن اسم الله بوصفه معبّرًا عن الصفات الإلهية: <g>ἁγιάζειν</g> (<g>ἅγιον</g>) <g>τὸ ὄ.</g> (<g>τ. Πατρός</g>، <g>Κυρίου</g>)، <r v=\"Matt.6.9\"></r>، <r v=\"Luke.1.49\"></r> <r v=\"Luke.11.2\"></r>؛ <g>ψάλλειν</g> (<g>ὁμολογεῖν</g>) <g>τῷ ὀ.</g>، <r v=\"Rom.15.9\"></r>، <r v=\"Heb.13.15\"></r>؛ <g>δοξάζειν</g> (<g>φανεροῦν</g>، <g>φοβεῖσθαι</g>) <g>τὸ ὄ.</g>، <r v=\"John.12.28\"></r> <r v=\"John.17.6\"></r>، <r v=\"John.17.26\"></r>، <r v=\"Rev.11.18\"></r> <r v=\"Rev.15.4\"></r>؛ <g>βλασφημεῖν</g>، <r v=\"Rom.2.24\"></r>، <r v=\"1Tim.6.1\"></r>، <r v=\"Rev.13.6\"></r>؛ وكذلك عن اسم المسيح: <g>τ. καλὸν ὄ.</g>؛ <g>πιστεύειν τῷ ὀ.</g>، <r v=\"1John.3.23\"></r>؛ <g>π. εἰς τ. ὄ.</g>، <r v=\"John.1.12\"></r> <r v=\"John.2.23\"></r> <r v=\"John.3.18\"></r>؛ <g>ὀνομάζειν τὸ ὄ.</g>، <r v=\"2Tim.2.19\"></r>؛ <g>κρατεῖν</g>، <r v=\"Rev.2.13\"></r>؛ <g>οὐκ ἀρνεῖσθαι</g>، <r v=\"Rev.3.8\"></r>؛ <g>ἐν τ. ὀ.</g>، <r v=\"Mark.9.38\"></r> <r v=\"Mark.16.17\"></r>، <r v=\"Luke.10.17\"></r>، <r v=\"John.14.13\"></r> <r v=\"John.16.23\"></r>، <r v=\"John.16.24\"></r> <r v=\"John.20.31\"></r>، <r v=\"Acts.3.6\"></r> <r v=\"Acts.4.12\"></r>، <r v=\"Eph.5.20\"></r>، <r v=\"1Pet.4.14\"></r>، وفي مواضع أخرى؛ <g>εἰς τ. ὄ. συνάγεσθαι</g>، <r v=\"Matt.18.20\"></r>؛ <g>ἕνεκεν τοῦ ὀ.</g>، <r v=\"Matt.19.29\"></r>؛ <g>διὰ τὸ ὄ.</g>، <r v=\"Matt.10.22\"></r>، <r v=\"Mark.13.13\"></r>، وفي مواضع أخرى؛ <g>διὰ τοῦ ὀ.</g>، <r v=\"1Cor.1.10\"></r>؛ <g>ὑπὲρ τοῦ ὀ.</g>، <r v=\"Acts.9.16\"></r>، <r v=\"Rom.1.5\"></r>، وفي مواضع أخرى؛ وهو نفسه مطلقًا، <r v=\"Acts.5.41\"></r>، <r v=\"3John.1.7\"></r>؛ <g>πρὸς τὸ ὄ.</g>، <r v=\"Acts.26.9\"></r>.</s> <s n=\"3.\"><b>سبب</b>، <b>داعٍ</b>، <b>علّة</b> : <r v=\"Mark.9.41\"></r> .</s> <s n=\"4.\">في اليونانية المتأخرة، <b>فرد</b>، <b>شخص / نَفْس</b>: <r v=\"Acts.1.15\"></r>، <r v=\"Rev.3.4\"></r> <r v=\"Rev.11.13\"></r>.</s>","en":"<f><o>ὄνομα</o>, <g>-τος, τό</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H8034\">שֵׁם</h>;]</e> </et> <s n=\"1.\">in general, <b>the name</b> by which a person or thing is called: <r v=\"Matt.10.2\"></r>, <r v=\"Mark.3.16\"></r>, <r v=\"Luke.1.63\"></r>, <r v=\"John.18.10\"></r>, al.; <g>ἄνθρωπος</g> (etc.), <g>ᾧ</g> (<g>οὗ</g>) <g>ὄ.</g> (<g>τ. ὄ</g>), sc. <g>ἦν</g> or <g>ἐστίν</g> (Bl., § 30, 3), <r v=\"Mark.14.32\"></r>, <r v=\"Luke.1.26\"></r>, <r v=\"Luke.1.27\"></r>; with same ellipsis, <g>καὶ τ. ὄ. αὐτοῦ</g> (<g>ὄ. αὐτῷ</g>), <r v=\"Luke.1.5\"></r>, <r v=\"John.1.6\"></r>, al.; <g>ὀνόματι</g>, seq. nom. prop., <r v=\"Matt.27.32\"></r>, <r v=\"Mark.5.22\"></r>, <r v=\"Luke.1.5\"></r>, <r v=\"Acts.5.1\"></r>, al.; acc. absol. (Bl., § 34, 7), <g>τοὔνομα</g> (= <g>τ. ὄνομα</g>), <r v=\"Matt.27.57\"></r>; <g>ὄ. μοι</g> (sc. <g>ἐστίν</g>; cf. Hom., <i>Od.</i>, ix, 366), <r v=\"Mark.5.9\"></r> (cf. <r v=\"Luke.8.30\"></r>); <g>ἔξειν ὄ.</g>, <r v=\"Rev.9.11\"></r>; <g>καλεῖν</g> (<g>ἐπιτιθέναι</g>) <g>ὄ.</g> (Bl., § 33, 1), <r v=\"Matt.1.21\"></r>, <r v=\"Mark.3.16\"></r>; <g>τ. ὄ. ἐν</g> (<g>τ.</g>) <g>βίβλῳ ζωῆς</g> (cf. Deiss., <i>LAE</i>, 121), <r v=\"Phil.4.3\"></r>, <r v=\"Rev.13.8\"></r>, cf. <r v=\"Luke.10.20\"></r> (<g>ἐν τ. οὐρανοῖς</g>); <g>ὄ. βλασφημίας</g>, <r v=\"Rev.13.1\"></r>; the name as opp. to the reality, <r v=\"Rev.3.1\"></r> (cf. Hdt., vii, 138); as a title: <r v=\"Eph.1.21\"></r>, <r v=\"Phil.2.9\"></r>, <r v=\"Phil.2.10\"></r> (Lft., in l.).</s> <s n=\"2.\">By a usage similar to that with ref. to Heb. <h n=\"H8034\">שֵׁם</h> (Lft., <i>Notes</i>, 106 f.), but also common in Hellenistic (M, <i>Pr.</i>, 100; Bl., § 39, 4; Deiss, <i>BS</i>, 146 f., 196 f.; <i>LAE</i>, 123<i>4</i>, of all that the name implies, of rank, authority, character, etc.: of acting on one's authority or in his behalf, <g>ἐν</g> (<g>εἰς</g>) <g>ὄ.</g>, c. gen. pers. (v. reff. supr.), <r v=\"Matt.10.41\"></r> <r v=\"Matt.21.9\"></r> <r v=\"Matt.28.19\"></r>, <r v=\"Mark.11.9\"></r>, <r v=\"Luke.13.35\"></r>, <r v=\"John.5.43\"></r>, <r v=\"Acts.8.16\"></r>, <r v=\"1Cor.1.13\"></r>; of the name Christian, <r v=\"1Pet.4.16\"></r>; esp. of the name of God as expressing the divine attributes: <g>ἁγιάζειν</g> (<g>ἅγιον</g>) <g>τὸ ὄ.</g> (<g>τ. Πατρός</g>, <g>Κυρίου</g>), <r v=\"Matt.6.9\"></r>, <r v=\"Luke.1.49\"></r> <r v=\"Luke.11.2\"></r>; <g>ψάλλειν</g> (<g>ὁμολογεῖν</g>) <g>τῷ ὀ.</g>, <r v=\"Rom.15.9\"></r>, <r v=\"Heb.13.15\"></r>; <g>δοξάζειν</g> (<g>φανεροῦν</g>, <g>φοβεῖσθαι</g>) <g>τὸ ὄ.</g>, <r v=\"John.12.28\"></r> <r v=\"John.17.6\"></r>, <r v=\"John.17.26\"></r>, <r v=\"Rev.11.18\"></r> <r v=\"Rev.15.4\"></r>; <g>βλασφημεῖν</g>, <r v=\"Rom.2.24\"></r>, <r v=\"1Tim.6.1\"></r>, <r v=\"Rev.13.6\"></r>; similarly, of the name of Christ: <g>τ. καλὸν ὄ.</g> (Deiss., <i>LAE</i>, 276); <g>πιστεύειν τῷ ὀ.</g>, <r v=\"1John.3.23\"></r>; <g>π. εἰς τ. ὄ.</g> (Bl., § 39, 4), <r v=\"John.1.12\"></r> <r v=\"John.2.23\"></r> <r v=\"John.3.18\"></r>; <g>ὀνομάζειν τὸ ὄ.</g>, <r v=\"2Tim.2.19\"></r>; <g>κρατεῖν</g>, <r v=\"Rev.2.13\"></r>; <g>οὐκ ἀρνεῖσθαι</g>, <r v=\"Rev.3.8\"></r>; <g>ἐν τ. ὀ.</g> (v. reff. supr.), <r v=\"Mark.9.38\"></r> <r v=\"Mark.16.17\"></r>, <r v=\"Luke.10.17\"></r>, <r v=\"John.14.13\"></r> <r v=\"John.16.23\"></r>, <r v=\"John.16.24\"></r> <r v=\"John.20.31\"></r>, <r v=\"Acts.3.6\"></r> <r v=\"Acts.4.12\"></r>, <r v=\"Eph.5.20\"></r>, <r v=\"1Pet.4.14\"></r>, al.; <g>εἰς τ. ὄ. συνάγεσθαι</g>, <r v=\"Matt.18.20\"></r>; <g>ἕνεκεν τοῦ ὀ.</g>, <r v=\"Matt.19.29\"></r>; <g>διὰ τὸ ὄ.</g>, <r v=\"Matt.10.22\"></r>, <r v=\"Mark.13.13\"></r>, al.; <g>διὰ τοῦ ὀ.</g>, <r v=\"1Cor.1.10\"></r>; <g>ὑπὲρ τοῦ ὀ.</g>, <r v=\"Acts.9.16\"></r>, <r v=\"Rom.1.5\"></r>, al.; id. absol., <r v=\"Acts.5.41\"></r>, <r v=\"3John.1.7\"></r>; <g>πρὸς τὸ ὄ.</g>, <r v=\"Acts.26.9\"></r>.</s> <s n=\"3.\"><b>cause</b>, <b>ground</b>, <b>reason</b> (in cl., usually in bad sense, <i>pretext</i>): <r v=\"Mark.9.41\"></r> (Swete, in l.; Dalman, <i>Words</i>, 305 f.).</s> <s n=\"4.\">In late Greek (Deiss., <i>BS</i>., 196 f.), <b>an individual</b>, <b>a person</b>: <r v=\"Acts.1.15\"></r>, <r v=\"Rev.3.4\"></r> <r v=\"Rev.11.13\"></r>.</s>"},"G3619":{"l":"οἰκοδομή","o":18,"ar":"<f>† <o>οἰκοδομή</o>، <g>-ῆς, ἡ</g></f> <s n=\"1.\">فعل <b>البناء</b>؛ وفي العهد الجديد دائمًا مجازيًا، <b>البنيان</b>، <b>البناء الروحي (التهذيب)</b>: <r v=\"Rom.14.19\"></r> <r v=\"Rom.15.2\"></r>، <r v=\"1Cor.14.26\"></r>، <r v=\"2Cor.10.8\"></r> <r v=\"2Cor.13.10\"></r>، <r v=\"Eph.4.29\"></r>؛ مع المضاف إليه المفعولي، <r v=\"1Cor.14.12\"></r>، <r v=\"2Cor.12.19\"></r>، <r v=\"Eph.4.12\"></r>، <r v=\"Eph.4.16\"></r>؛ <g>λαλεῖν</g>، <g>λαβεῖν</g>، <g>οἰ.</g>، <r v=\"1Cor.14.3\"></r>.</s> <s n=\"2.\">= <g>οἰκοδόμημα</g>، <b>بناء / مبنى</b>: <r v=\"Matt.24.1\"></r>، <r v=\"Mark.13.1\"></r>، <r v=\"Mark.13.2\"></r>؛ مجازيًا، <r v=\"1Cor.3.9\"></r>، <r v=\"2Cor.5.1\"></r>، <r v=\"Eph.2.21\"></r>.†</s>","en":"<f>† <o>οἰκοδομή</o>, <g>-ῆς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>οἶκος</g>, + <g>δέμω</g>, <i>to build</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"1Chr.29.1\"></r> A (<h n=\"H1002\">בִּירָה</h>), <r v=\"Ezek.17.17\"></r> <r v=\"Ezek.40.2\"></r> (<h n=\"H1129\">בּנה</h>, <h n=\"H4011\">מִבְנֶה</h>), <r v=\"Sir.22.16\"></r> <r v=\"Sir.40.19\"></r>, al.;]</e> <e t=\"derivation\">= cl. <g>οἰκοδομία</g> (q.v.), <g>-δόμησις</g> (Thuc., Plat.),</e> </et> <s n=\"1.\">the act of <b>building</b>; in NT always metaph., <b>building up</b>, <b>edifying</b>: <r v=\"Rom.14.19\"></r> <r v=\"Rom.15.2\"></r>, <r v=\"1Cor.14.26\"></r>, <r v=\"2Cor.10.8\"></r> <r v=\"2Cor.13.10\"></r>, <r v=\"Eph.4.29\"></r>; c. gen. obj., <r v=\"1Cor.14.12\"></r>, <r v=\"2Cor.12.19\"></r>, <r v=\"Eph.4.12\"></r>, <r v=\"Eph.4.16\"></r>; <g>λαλεῖν</g>, <g>λαβεῖν</g>, <g>οἰ.</g>, <r v=\"1Cor.14.3\"></r>.</s> <s n=\"2.\">= <g>οἰκοδόμημα</g>, <b>a building</b>: <r v=\"Matt.24.1\"></r>, <r v=\"Mark.13.1\"></r>, <r v=\"Mark.13.2\"></r>; metaph., <r v=\"1Cor.3.9\"></r>, <r v=\"2Cor.5.1\"></r>, <r v=\"Eph.2.21\"></r>.†</s>"},"G3687":{"l":"ὀνομάζω","o":10,"ar":"<f><o>ὀνομάζω</o></f> <s n=\"1.\"><b>يُسمّي</b>، <b>يذكر</b>، أو <b>ينادي بالاسم</b>: <r v=\"Acts.19.13\"></r>؛ المبني للمجهول، <r v=\"Rom.15.20\"></r>، <r v=\"Eph.1.21\"></r> <r v=\"Eph.5.3\"></r>؛ عن استعمال الاسم الإلهي في التسبيح والعبادة، <r v=\"2Tim.2.19\"></r> (السبعينية، <r v=\"Num.16.26\"></r>؛ قارن <r v=\"Isa.52.11\"></r>، <r v=\"Amos.6.10\"></r>).</s> <s n=\"2.\"><b>يُسمّي، يدعو</b>، <b>يُطلق اسمًا على</b>: <r v=\"Mark.3.14\"></r>، <r v=\"Luke.6.13\"></r>، <r v=\"Luke.6.14\"></r>؛ المبني للمجهول، <r v=\"1Cor.5.11\"></r>؛ يليه <g>ἐξ</g>، <r v=\"Eph.3.15\"></r> (قارن <g>ἐπ-ονομάζω</g>).†</s>","en":"<f><o>ὀνομάζω</o></f> <et> <e t=\"derivation\">(&lt; <g>ὄνομα</g>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H2142\">זכר</h>, <h n=\"H5344\">נקב</h>, <h n=\"H7121\">קרא</h>;]</e> </et> <s n=\"1.\"><b>to name</b>, <b>mention</b>, or <b>address by name</b>: <r v=\"Acts.19.13\"></r>; pass., <r v=\"Rom.15.20\"></r>, <r v=\"Eph.1.21\"></r> <r v=\"Eph.5.3\"></r>; of the use of the Divine name in praise and worship, <r v=\"2Tim.2.19\"></r> (LXX, <r v=\"Num.16.26\"></r>; cf. <r v=\"Isa.52.11\"></r>, <r v=\"Amos.6.10\"></r>).</s> <s n=\"2.\"><b>to name, call</b>, <b>give a name to</b>: <r v=\"Mark.3.14\"></r> (T, R, txt. om.), <r v=\"Luke.6.13\"></r>, <r v=\"Luke.6.14\"></r>; pass., <r v=\"1Cor.5.11\"></r>; seq. <g>ἐξ</g> (cl.), <r v=\"Eph.3.15\"></r> (cf. <g>ἐπ-ονομάζω</g>).†</s>"},"G3631":{"l":"οἶνος","o":34,"ar":"<f><o>οἶνος</o>، <g>-ου, ὁ</g>،</f> <s><b>خمر</b>: <r v=\"Matt.9.17\"></r>، <r v=\"Luke.1.15\"></r>، <r v=\"John.2.3\"></r>، وفي مواضع أخرى؛ <g>οἴνῳ προσέχειν</g>، <r v=\"1Tim.3.8\"></r>؛ <g>δουλοῦσθαι</g>، <r v=\"Titus.2.3\"></r>. مجازيًا، <r v=\"Rev.14.8\"></r>، <r v=\"Rev.14.10\"></r> <r v=\"Rev.16.19\"></r> <r v=\"Rev.17.2\"></r> <r v=\"Rev.18.3\"></r> <r v=\"Rev.19.15\"></r>. كنايةً عن <g>ἄμπελος</g>، <r v=\"Rev.6.6\"></r>.</s>","en":"<f><o>οἶνος</o>, <g>-ου, ὁ</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3196\">יַיִן</h> also for <h n=\"H8492\">תִּירוֹשׁ</h>, etc.;]</e> </et> <s><b>wine</b>: <r v=\"Matt.9.17\"></r>, <r v=\"Luke.1.15\"></r>, <r v=\"John.2.3\"></r>, al.; <g>οἴνῳ προσέχειν</g>, <r v=\"1Tim.3.8\"></r>; <g>δουλοῦσθαι</g>, <r v=\"Titus.2.3\"></r>. Metaph., <r v=\"Rev.14.8\"></r>, <r v=\"Rev.14.10\"></r> <r v=\"Rev.16.19\"></r> <r v=\"Rev.17.2\"></r> <r v=\"Rev.18.3\"></r> <r v=\"Rev.19.15\"></r>. By meton. for <g>ἄμπελος</g>, <r v=\"Rev.6.6\"></r>.</s>"},"G3650":{"l":"ὅλος","o":111,"ar":"<f><o>ὅλος</o>، <g>-η, -ον</g>،</f> <s>عن الأشخاص والأشياء، <b>كل، كامل</b>، <b>بأكمله</b>، <b>تام</b>؛ <s n=\"1.\">عن المعاني غير المحددة، مع اسم بدون أداة التعريف: <r v=\"Luke.5.5\"></r>، <r v=\"Acts.11.26\"></r> <r v=\"Acts.28.30\"></r>، <r v=\"Titus.1.11\"></r>؛ <g>ὅλον ἄνθρωπον</g> (<i>إنسانًا كاملًا</i>)، <r v=\"John.7.23\"></r>؛ <g>ὅλη Ἰερουσαλήμ</g> (= <g>πᾶσα Ἰ</g>، <r v=\"Matt.2.3\"></r>)، <r v=\"Acts.21.31\"></r>.</s> <s n=\"2.\">محدد، مع أداة التعريف؛ <s n=\"(a)\">قبل الاسم: <r v=\"Matt.4.23\"></r>، <r v=\"Matt.4.24\"></r>، <r v=\"Luke.8.39\"></r>، <r v=\"1Cor.12.17\"></r>، وفي مواضع أخرى؛</s> <s n=\"(b)\">بعد الاسم: <r v=\"Mark.1.33\"></r>، <r v=\"Luke.9.25\"></r>، <r v=\"John.4.53\"></r>، <r v=\"Acts.21.30\"></r>، وفي مواضع أخرى؛</s> <s n=\"(c)\">في اليونانية الكلاسيكية: بين أداة التعريف والاسم، حين يكون الاسم اسم معنى.</s> </s> <s n=\"3.\">ملحقًا بصفة أو فعل: <r v=\"Matt.13.33\"></r>، <r v=\"Luke.13.21\"></r>، <r v=\"John.9.34\"></r>، وفي مواضع أخرى؛ ظرفيًا، <g>δι ̓ ὅλου</g>، <b>كله، من أوله إلى آخره</b>، <r v=\"John.19.23\"></r>.</s> </s>","en":"<f><o>ὅλος</o>, <g>-η, -ον</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3605\">כֹּל</h>;]</e> </et> <s>of persons and things, <b>whole</b>, <b>entire</b>, <b>complete</b>; <s n=\"1.\">of indefinite ideas, c. subst. anarth.: <r v=\"Luke.5.5\"></r>, <r v=\"Acts.11.26\"></r> <r v=\"Acts.28.30\"></r>, <r v=\"Titus.1.11\"></r>; <g>ὅλον ἄνθρωπον</g> (<i>an entire man</i>; v. Field, <i>Notes</i>, 93), <r v=\"John.7.23\"></r>; <g>ὅλη Ἰερουσαλήμ</g> (= <g>πᾶσα Ἰ</g>, <r v=\"Matt.2.3\"></r>; v. Bl., § 47, 9), <r v=\"Acts.21.31\"></r>.</s> <s n=\"2.\">Definite, c. art.; <s n=\"(a)\">preceding subst.: <r v=\"Matt.4.23\"></r>, <r v=\"Matt.4.24\"></r>, <r v=\"Luke.8.39\"></r>, <r v=\"1Cor.12.17\"></r>, al.;</s> <s n=\"(b)\">following subst.: <r v=\"Mark.1.33\"></r>, <r v=\"Luke.9.25\"></r>, <r v=\"John.4.53\"></r>, <r v=\"Acts.21.30\"></r>, al.;</s> <s n=\"(c)\">between art. and subst., where subst. is an abstract noun (Plat., al.).</s> </s> <s n=\"3.\">Attached to adj. or verb: <r v=\"Matt.13.33\"></r>, <r v=\"Luke.13.21\"></r>, <r v=\"John.9.34\"></r>, al.; adverbially, <g>δι ̓ ὅλου</g> (MM, xviii), <r v=\"John.19.23\"></r>.</s> </s>"},"G3676":{"l":"ὅμως","o":3,"ar":"<f><o>ὅμως</o>،</f> ظرف <s><b>ومع ذلك</b>: <g>ὅ. μέντοι</g>، <b>ولكن مع ذلك</b>، <b>غير أنّ</b>، <r v=\"John.12.42\"></r>؛ بالتقديم والتأخير، في غير موضعه الطبيعي، <r v=\"1Cor.14.7\"></r>، <r v=\"Gal.3.15\"></r>.†</s>","en":"<f><o>ὅμως</o>,</f> adv. <et> <e t=\"derivation\">(&lt; <g>ὁμίς</g>),</e> </et> <s><b>yet</b>: <g>ὅ. μέντοι</g>, <b>but yet</b>, <b>nevertheless</b>, <r v=\"John.12.42\"></r>; by hyperbaton, out of its proper position, <r v=\"1Cor.14.7\"></r>, <r v=\"Gal.3.15\"></r> (but v. Bl., § 77, 14).†</s>"},"G3691":{"l":"ὄξύς","o":null,"ar":"<f><o>ὀξύς</o>، <g>-εῖα, -ύ</g>،</f> <s n=\"1.\"><b>حادّ، ماضٍ</b>: <r v=\"Rev.1.16\"></r>، <r v=\"Rev.2.12\"></r>، <r v=\"Rev.14.14\"></r>، <r v=\"Rev.14.17\"></r>، <r v=\"Rev.14.18\"></r>، <r v=\"Rev.19.15\"></r>.</s> <s n=\"2.\">عن الحركة: <b>سريع</b>: <r v=\"Rom.3.15\"></r> (وفي السبعينية <g>ταχινός</g>).†</s>","en":"<f><o>ὀξύς</o>, <g>-εῖα, -ύ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Ps.57.4\"></r>, al. (<h n=\"H2299\">חַד</h>), <r v=\"Amos.2.15\"></r> (<h n=\"H7031\">קַל</h>), <r v=\"Isa.5.28\"></r> (<h n=\"H8150\">שׁנן</h>), etc.;]</e> </et> <s n=\"1.\"><b>sharp</b>: <r v=\"Rev.1.16\"></r> <r v=\"Rev.2.12\"></r> <r v=\"Rev.14.14\"></r>, <r v=\"Rev.14.17\"></r>, <r v=\"Rev.14.18\"></r> <r v=\"Rev.19.15\"></r>.</s> <s n=\"2.\">Of motion, <b>swift</b>: <r v=\"Rom.3.15\"></r> (LXX <g>ταχινός</g>).†</s>"},"G3602":{"l":"ὀδυρμός","o":2,"ar":"<f><o>ὀδυρμός</o>، <g>-οῦ, ὁ</g></f> <s><b>نَوْح</b>، <b>عويل</b>: <r v=\"Matt.2.18\"></r><i>(السبعينية)</i>، <r v=\"2Cor.7.7\"></r>.†</s>","en":"<f><o>ὀδυρμός</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>ὀδύρομαι</g>, <i>to lament</i>),</e> <e t=\"septuagint\">[in LXX : <r v=\"Jer.31.15\"></r> (<h n=\"H8563\">תַּמְרוּריִם</h>), <r v=\"2Macc.11.6\"></r>*;]</e> </et> <s><b>lamentation</b>, <b>mourning</b>: <r v=\"Matt.2.18\"></r><i>(LXX)</i>, <r v=\"2Cor.7.7\"></r>.†</s>"},"G3601":{"l":"ὀδύνη","o":2,"ar":"<f><o>ὀδύνη</o>، <g>-ης, ἡ</g>،</f> <s><b>ألم</b>، <b>وجع، ضيق</b>، في الجسد أو النفس: <r v=\"Rom.9.2\"></r>، <r v=\"1Tim.6.10\"></r>.†</s>","en":"<f><o>ὀδύνη</o>, <g>-ης, ἡ</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H3015\">יָגוֹן</h>, <h n=\"H4751\">מַר</h>, etc. (26 words in all);]</e> </et> <s><b>pain</b>, <b>distress</b>, of body or mind: <r v=\"Rom.9.2\"></r>, <r v=\"1Tim.6.10\"></r>.†</s>"},"G3657":{"l":"ὁμιλία","o":1,"ar":"<f><o>ὁμιλία</o>، <g>-ας, ἡ</g></f> <s><b>معاشرة</b>، <b>مخالطة</b>: <r v=\"1Cor.15.33\"></r>.†</s>","en":"<f><o>ὁμιλία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>ὅμιλος</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Exod.21.10\"></r> (<h n=\"H5772\">עֹנָה</h>), al.;]</e> </et> <s><b>company</b>, <b>association</b>: <r v=\"1Cor.15.33\"></r>.†</s>"},"G3652":{"l":"Ὀλυμπᾶς","o":1,"ar":"<f><o>Ὀλυμπᾶς</o></f> <s><b>أولمباس</b>: <r v=\"Rom.16.15\"></r>.†</s>","en":"<f><o>Ὀλυμπᾶς</o></f> <et> <e t=\"derivation\">(perh. contr. fr. <g>Ὀλυμπιόδωρος</g>, Bl., § 29), <g>-ᾶ</g>,</e> </et> <s><b>Olympas</b>: <r v=\"Rom.16.15\"></r>.†</s>"},"G3699":{"l":"ὅπου","o":82,"ar":"<f><o>ὅπου</o>،</f> ظرف <s>للمكان، يقابل <g>ποῦ</g> (انظره)، <b>حيث</b>. <s n=\"I.\">أصلاً، للمكان، <s n=\"1.\"><b>حيث</b>؛ <s n=\"(a)\">في الجمل الموصولة، مع الإخباري: <r v=\"Matt.25.24\"></r>، <r v=\"Matt.25.26\"></r>، <r v=\"Mark.2.4\"></r> <r v=\"Mark.4.5\"></r>، <r v=\"Mark.4.15\"></r> <r v=\"Mark.5.40\"></r> <r v=\"Mark.13.14\"></r>، <r v=\"John.3.8\"></r> <r v=\"John.6.62\"></r> <r v=\"John.7.34\"></r>، <r v=\"John.7.36\"></r> <r v=\"John.11.32\"></r> <r v=\"John.14.3\"></r> <r v=\"John.17.24\"></r> <r v=\"John.20.19\"></r>، <r v=\"Rom.15.20\"></r>، <r v=\"Rev.2.13\"></r>؛ بعد أسماء المكان، بدلاً من عبارة موصولة بحرف جر (<g>ἐν ᾧ.</g>، إلخ)، <r v=\"Matt.6.19\"></r>، <r v=\"Matt.6.20\"></r> <r v=\"Matt.13.5\"></r> <r v=\"Matt.26.57\"></r> <r v=\"Matt.28.6\"></r>، <r v=\"Mark.6.55\"></r> <r v=\"Mark.9.48\"></r>، <r v=\"Luke.12.33\"></r>، <r v=\"John.1.28\"></r> <r v=\"John.4.20\"></r>، <r v=\"John.4.46\"></r> <r v=\"John.6.23\"></r> <r v=\"John.7.42\"></r> <r v=\"John.10.40\"></r> <r v=\"John.11.30\"></r> <r v=\"John.12.1\"></r> <r v=\"John.18.1\"></r>، <r v=\"John.18.20\"></r> <r v=\"John.19.18\"></r>، <r v=\"John.19.20\"></r>، <r v=\"John.19.41\"></r> <r v=\"John.20.12\"></r>، <r v=\"Acts.17.1\"></r>، <r v=\"Rev.2.13\"></r> <r v=\"Rev.11.8\"></r> <r v=\"Rev.20.10\"></r>؛ يليه <g>ἐκεῖ.</g>، <r v=\"Matt.6.21\"></r>، <r v=\"Luke.12.34\"></r> <r v=\"Luke.17.37\"></r>، <r v=\"John.12.26\"></r>؛ وكذلك مع تكرار زائد (= العبرية <h n=\"H834\">אֲשֶׁר</h> . . . <h n=\"H8033\">שָׁם</h>؛ الآرامية <h>דְּ</h> . . . <h n=\"H856\">תַּמָּן</h>؛ قارن <r v=\"Gen.13.3\"></r>)، <g>ὅ.</g> . . . <g>ἐκεῖ</g>، <r v=\"Rev.12.6\"></r>، <r v=\"Rev.12.14\"></r>؛ <g>ὅ.</g> . . . <g>ἐπ' αὐτῶν</g>، <r v=\"Rev.17.9\"></r>؛ <g>ὅ. ἄν</g>، <b>حيثما</b>، مع الماضي الناقص الإخباري، <r v=\"Mark.6.56\"></r>؛ مع المضارع في صيغة الاحتمال، <r v=\"Matt.24.28\"></r>؛ <g>ὅ. ἐάν</g>، <r v=\"Matt.26.13\"></r>، <r v=\"Mark.6.10\"></r> <r v=\"Mark.9.18\"></r> <r v=\"Mark.14.9\"></r>، <r v=\"Mark.14.14\"></r>؛</s> <s n=\"(b)\">في السؤال غير المباشر، مع الماضي البسيط في صيغة الاحتمال: <r v=\"Mark.14.14\"></r>، <r v=\"Luke.22.11\"></r>.</s> </s> <s n=\"2.\">عند الكتّاب المتأخرين، مع أفعال الحركة، = <g>ὅποι</g>، <b>إلى حيث</b>: مع الإخباري، <r v=\"John.8.21\"></r>، <r v=\"John.8.22\"></r> <r v=\"John.13.33\"></r>، <r v=\"John.13.36\"></r> <r v=\"John.14.4\"></r> <r v=\"John.21.18\"></r>، <r v=\"Heb.6.20\"></r>، <r v=\"Jas.3.4\"></r>؛ <g>ὅ. ἄν</g>، <b>إلى حيثما</b>، مع المضارع الإخباري، <r v=\"Rev.14.4\"></r>؛ مع صيغة الاحتمال، <r v=\"Luke.9.57\"></r>؛ <g>ὅ. ἐάν</g>، <r v=\"Matt.8.19\"></r>.</s> </s> <s n=\"II.\">بغير المعنى المكاني الدقيق، <s n=\"1.\">للزمن أو الحال: <r v=\"Col.3.11\"></r>، <r v=\"Heb.9.16\"></r> <r v=\"Heb.10.18\"></r>، <r v=\"Jas.3.16\"></r>، <r v=\"2Pet.2.11\"></r>.</s> <s n=\"2.\">للسبب أو العلة (<i>إذ</i>، <i>بما أن</i>): <r v=\"1Cor.3.3\"></r>.†</s> </s> </s>","en":"<f><o>ὅπου</o>,</f> adv. <s>of place, correlat. of <g>ποῦ</g> (q.v.), <b>where</b>. <s n=\"I.\">Prop., of place, <s n=\"1.\"><b>where</b>; <s n=\"(a)\">in relative sentences, c. indic: <r v=\"Matt.25.24\"></r>, <r v=\"Matt.25.26\"></r>, <r v=\"Mark.2.4\"></r> <r v=\"Mark.4.5\"></r>, <r v=\"Mark.4.15\"></r> <r v=\"Mark.5.40\"></r> <r v=\"Mark.13.14\"></r>, <r v=\"John.3.8\"></r> <r v=\"John.6.62\"></r> <r v=\"John.7.34\"></r>, <r v=\"John.7.36\"></r> <r v=\"John.11.32\"></r> <r v=\"John.14.3\"></r> <r v=\"John.17.24\"></r> <r v=\"John.20.19\"></r>, <r v=\"Rom.15.20\"></r>, <r v=\"Rev.2.13\"></r>; after nouns of place, for relat. prepositional phrase (<g>ἐν ᾧ.</g>, etc.), <r v=\"Matt.6.19\"></r>, <r v=\"Matt.6.20\"></r> <r v=\"Matt.13.5\"></r> <r v=\"Matt.26.57\"></r> <r v=\"Matt.28.6\"></r>, <r v=\"Mark.6.55\"></r> <r v=\"Mark.9.48\"></r>, <r v=\"Luke.12.33\"></r>, <r v=\"John.1.28\"></r> <r v=\"John.4.20\"></r>, <r v=\"John.4.46\"></r> <r v=\"John.6.23\"></r> <r v=\"John.7.42\"></r> <r v=\"John.10.40\"></r> <r v=\"John.11.30\"></r> <r v=\"John.12.1\"></r> <r v=\"John.18.1\"></r>, <r v=\"John.18.20\"></r> <r v=\"John.19.18\"></r>, <r v=\"John.19.20\"></r>, <r v=\"John.19.41\"></r> <r v=\"John.20.12\"></r>, <r v=\"Acts.17.1\"></r>, <r v=\"Rev.2.13\"></r> <r v=\"Rev.11.8\"></r> <r v=\"Rev.20.10\"></r>; seq. <g>ἐκεῖ.</g>, <r v=\"Matt.6.21\"></r>, <r v=\"Luke.12.34\"></r> <r v=\"Luke.17.37\"></r>, <r v=\"John.12.26\"></r>; id. pleonast. (= Heb. <h n=\"H834\">אֲשֶׁר</h> . . . <h n=\"H8033\">שָׁם</h>; Aram. <h>דְּ</h> . . . <h n=\"H856\">תַּמָּן</h>; cf. <r v=\"Gen.13.3\"></r>), <g>ὅ.</g> . . . <g>ἐκεῖ</g>, <r v=\"Rev.12.6\"></r>, <r v=\"Rev.12.14\"></r>; <g>ὅ.</g> . . . <g>ἐπ' αὐτῶν</g>, <r v=\"Rev.17.9\"></r>; <g>ὅ. ἄν</g>, <b>wherever</b> (M, <i>Pr.</i>, 168), c. impf. indic., <r v=\"Mark.6.56\"></r>; c. pres. subjc., <r v=\"Matt.24.28\"></r>; <g>ὅ. ἐάν</g>, <r v=\"Matt.26.13\"></r>, <r v=\"Mark.6.10\"></r> <r v=\"Mark.9.18\"></r> <r v=\"Mark.14.9\"></r>, <r v=\"Mark.14.14\"></r>;</s> <s n=\"(b)\">in quaest. indir., c. aor. subjc.: <r v=\"Mark.14.14\"></r>, <r v=\"Luke.22.11\"></r>.</s> </s> <s n=\"2.\">In late writers (sometimes also in cl.; Bl., § 25, 2), with verbs of motion, = <g>ὅποι</g>, <b>whither</b>: c. indic., <r v=\"John.8.21\"></r>, <r v=\"John.8.22\"></r> <r v=\"John.13.33\"></r>, <r v=\"John.13.36\"></r> <r v=\"John.14.4\"></r> <r v=\"John.21.18\"></r>, <r v=\"Heb.6.20\"></r>, <r v=\"Jas.3.4\"></r>; <g>ὅ. ἄν</g>, <b>whithersoever</b>, c. pres. ind., <r v=\"Rev.14.4\"></r>; subjc., <r v=\"Luke.9.57\"></r>; <g>ὅ. ἐάν</g>, <r v=\"Matt.8.19\"></r>.</s> </s> <s n=\"II.\">Without strict local sense, <s n=\"1.\">of time or condition: <r v=\"Col.3.11\"></r>, <r v=\"Heb.9.16\"></r> <r v=\"Heb.10.18\"></r>, <r v=\"Jas.3.16\"></r>, <r v=\"2Pet.2.11\"></r>.</s> <s n=\"2.\">Of cause or reason (AV, <i>whereas</i>): <r v=\"1Cor.3.3\"></r>.†</s> </s> </s>"},"G3680":{"l":"ὀνειδισμός","o":5,"ar":"<f>† <o>ὀνειδισμός</o>، <g>-οῦ, ὁ</g></f> <s><b>تعيير، عار</b>: <r v=\"Rom.15.3\"></r>، <r v=\"Heb.10.33\"></r>؛ <g>εἰς ὀ. ἐμπεσεῖν</g>، <r v=\"1Tim.3.7\"></r>؛ <g>ὁ ὀ. τοῦ Χριστοῦ</g>، <r v=\"Heb.11.26\"></r> <r v=\"Heb.13.13\"></r>.†</s>","en":"<f>† <o>ὀνειδισμός</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(<g>ὀνειδίζω</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2781\">חֶרְפָּה</h>;]</e> </et> <s><b>a reproach</b>: <r v=\"Rom.15.3\"></r>, <r v=\"Heb.10.33\"></r>; <g>εἰς ὀ. ἐμπεσεῖν</g>, <r v=\"1Tim.3.7\"></r>; <g>ὁ ὀ. τοῦ Χριστοῦ</g>, <r v=\"Heb.11.26\"></r> <r v=\"Heb.13.13\"></r>.†</s>"},"G3637":{"l":"ὀκταήμερος","o":1,"ar":"<f>*† <o>ὀκταήμερος</o>، <g>-ον</g></f> <s><b>في اليوم الثامن</b>، <b>ابن ثمانية أيام</b>: مع القابل للإشارة، <g>περιτομῇ ὀ.</g>، <r v=\"Phil.3.5\"></r> (وكلمات هذا الوزن تدل على <i>المدة</i>، قارن <g>τεταρταῖος</g>).†</s>","en":"<f>*† <o>ὀκταήμερος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>ὀκτώ</g>, <g>ἡμέρα</g>),</e> </et> <s><b>of the eighth day</b>, <b>eight days old</b>: c. dat. ref., <g>περιτομῇ ὀ.</g>, <r v=\"Phil.3.5\"></r> (words of this class denote <i>duration</i>, cf. <g>τεταρταῖος</g>).†</s>"},"G3679":{"l":"ὀνειδίζω","o":9,"ar":"<f><o>ὀνειδίζω</o></f> <s><b>عيّر</b>، <b>وبّخ</b>: مطلقًا: <r v=\"Jas.1.5\"></r>؛ مع منصوب الشخص (وفي الكلاسيكية أكثر مع قابل الشخص): <r v=\"Matt.5.11\"></r>، <r v=\"Mark.15.32\"></r>، <r v=\"Mark.15.34\"></r>، <r v=\"Luke.6.22\"></r>، <r v=\"Rom.15.3\"></r><i>(السبعينية)</i>؛ <g>τ. πόλεις</g>: <r v=\"Matt.11.20\"></r>؛ المبني للمجهول: <r v=\"1Tim.4.10\"></r>، <r v=\"1Pet.4.14\"></r>؛ مع منصوب الشيء: <r v=\"Mark.16.14\"></r>؛ مع منصوبين: <r v=\"Matt.27.44\"></r>.†</s>","en":"<f><o>ὀνειδίζω</o></f> <et> <e t=\"derivation\">(&lt; <g>ὄνειδος</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2778\">חרף</h> pi.;]</e> </et> <s><b>to reproach</b>, <b>upbraid</b>: absol., <r v=\"Jas.1.5\"></r>; c. acc. pers. (in cl. more freq. c. dat. pers.; Bl., § 34, 2; WM, 278), <r v=\"Matt.5.11\"></r>, <r v=\"Mark.15.32\"></r>, <r v=\"Mark.15.34\"></r>, WH, mg., <r v=\"Luke.6.22\"></r>, <r v=\"Rom.15.3\"></r><i>(LXX)</i>; <g>τ. πόλεις</g>, <r v=\"Matt.11.20\"></r>; pass., <r v=\"1Tim.4.10\"></r>, WH, mg., <r v=\"1Pet.4.14\"></r>; c. acc. rei, <r v=\"Mark.16.14\"></r>; c. dupl. acc., <r v=\"Matt.27.44\"></r>.†</s>"},"G3610":{"l":"οἰκέτης","o":4,"ar":"<f><o>οἰκέτης</o>، <g>-ου, ὁ</g></f> <s><b>خادم بيت</b>: <r v=\"Luke.16.13\"></r>، <r v=\"Rom.14.4\"></r>؛ في الجمع: <r v=\"Acts.10.7\"></r>، <r v=\"1Pet.2.18\"></r>. (وقد يشمل الجمع جميع أهل البيت، أي <b>العائلة</b>، <g>οἰκετεία.</g>؛ قارن <r v=\"Sir.4.30\"></r>، <r v=\"Sir.6.11\"></r>.)†</s>","en":"<f><o>οἰκέτης</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>οἰκέω</g>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H5650\">עֶבֶד</h>;]</e> </et> <s><b>a house-servant</b>: <r v=\"Luke.16.13\"></r>, <r v=\"Rom.14.4\"></r>; pl., <r v=\"Acts.10.7\"></r>, <r v=\"1Pet.2.18\"></r>. (In Plat., Hdt., <r v=\"Sir.4.30\"></r> <r v=\"Sir.6.11\"></r>, the pl. includes all the inmates of the house, the <b>familia</b>, <g>οἰκετεία.</g>.)†</s> <sy><i>SYN.</i>: v.s. <g>διάκονος</g>.</sy>"},"G3639":{"l":"ὀλέθριος","o":4,"ar":"<f><o>ὀλέθριος</o>، <g>-ον</g></f> <s><b>مُهلك</b>، <b>مميت</b>: <g>δίκην</g>: <r v=\"2Thess.1.9\"></r>.†</s>","en":"<f><o>ὀλέθριος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(also <g>-α, -ον</g>, as in <r v=\"Wis.18.15\"></r>),</e> <e t=\"septuagint\">[in LXX : <r v=\"1Kgs.20.42\"></r> (<h n=\"H2764\">חֵרָם</h>), <r v=\"Wis.18.15\"></r>*;]</e> </et> <s><b>destructive</b>, <b>deadly</b>: <g>δίκην</g>, <r v=\"2Thess.1.9\"></r>, L, txt. (for <g>ὄλεθρος</g>, q.v.).†</s>"},"G3627":{"l":"οἰκτείρω","o":1,"ar":"<f><o>οἰκτείρω</o></f> <s><b>رأف</b>، <b>تحنّن</b> على. مع منصوب الشخص: <r v=\"Rom.9.15\"></r><i>(السبعينية)</i>.†</s>","en":"<f><o>οἰκτείρω</o></f> <et> <e t=\"derivation\">(&lt; <g>οἶκτος</g>, <i>pity</i>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H7355\">רחם</h> pi., <h n=\"H2603\">חנן</h>, etc.;]</e> </et> <s><b>to pity</b>, <b>have compassion</b> on. c. acc. pers., <r v=\"Rom.9.15\"></r><i>(LXX)</i>.†</s> <sy><i>SYN.</i>: <g>ἐλεέω</g>, q.v.</sy>"},"G3697":{"l":"ὁποῖος","o":5,"ar":"<f><o>ὁποῖος</o>، <g>-οία, -οῖον</g>،</f> <s><b>أيّ نوع، كيف</b>: <r v=\"1Cor.3.13\"></r>، <r v=\"Gal.2.6\"></r>، <r v=\"1Thess.1.9\"></r>، <r v=\"Jas.1.24\"></r>؛ <g>τοιοῦτος ὁ.</g>، <b>مثل، كما</b>، <r v=\"Acts.26.29\"></r>.†</s>","en":"<f><o>ὁποῖος</o>, <g>-οία, -οῖον</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Song.5.10\"></r>, <r v=\"2Macc.11.37\"></r>*;]</e> </et> <s><b>of what sort</b>: <r v=\"1Cor.3.13\"></r>, <r v=\"Gal.2.6\"></r>, <r v=\"1Thess.1.9\"></r>, <r v=\"Jas.1.24\"></r>; <g>τοιοῦτος ὁ.</g>, <b>such as</b>, <r v=\"Acts.26.29\"></r>.†</s>"},"G3683":{"l":"Ὀνησίφορος","o":2,"ar":"<f><o>Ὀνησίφορος</o>، <g>-ου, ὁ</g></f> <s><b>أنيسيفورس</b>: <r v=\"2Tim.1.16\"></r> <r v=\"2Tim.4.19\"></r>.†</s>","en":"<f><o>Ὀνησίφορος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(i.e. <i>bringing advantage</i>),</e> </et> <s><b>Onesiphorus</b>: <r v=\"2Tim.1.16\"></r> <r v=\"2Tim.4.19\"></r>.†</s>"},"G3642":{"l":"ὀλιγόψυχος","o":1,"ar":"<f>† <o>ὀλιγόψυχος</o>، <g>-ον</g></f> <s><b>صغير النفس، خائر العزيمة</b>: <r v=\"1Thess.5.14\"></r>.†</s>","en":"<f>† <o>ὀλιγόψυχος</o>, <g>-ον</g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Isa.35.4\"></r> (<h n=\"H4116\">מהר</h> ni.), etc.;]</e> </et> <s><b>faint-hearted</b>: <r v=\"1Thess.5.14\"></r>.†</s>"},"G3696":{"l":"ὅπλον","o":6,"ar":"<f><o>ὅπλον</o>، <g>-ου, τό</g>،</f> <s n=\"1.\"><b>أداة</b>، <b>آلة</b>، <b>وسيلة</b>: <g>ὅπλα ἀδικίας</g> (عكس <g>ὅ. δικαιοσύνης</g>)، <r v=\"Rom.6.13\"></r>.</s> <s n=\"2.\">كثيرًا في الجمع: <b>أسلحة</b>، <b>عُدّة حرب</b>: <r v=\"John.18.3\"></r>، <r v=\"2Cor.10.4\"></r>؛ مجازيًا، <g>τ. φωτός</g>، <r v=\"Rom.13.12\"></r>؛ <g>τ. δικαιοσύνης</g>، <r v=\"2Cor.6.7\"></r>.†</s>","en":"<f><o>ὅπλον</o>, <g>-ου, τό</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H4043\">מָגֵן</h>, <h n=\"H6793\">צִנָּה</h>, etc.;]</e> </et> <s n=\"1.\"><b>a tool</b>, <b>implement</b>, <b>instrument</b>: <g>ὅπλα ἀδικίας</g> (opp. to <g>ὅ. δικαιοσύνης</g>), <r v=\"Rom.6.13\"></r>.</s> <s n=\"2.\">Freq., in pl., <b>arms</b>, <b>weapons</b>: <r v=\"John.18.3\"></r>, <r v=\"2Cor.10.4\"></r>; metaph., <g>τ. φωτός</g>, <r v=\"Rom.13.12\"></r>; <g>τ. δικαιοσύνης</g>, <r v=\"2Cor.6.7\"></r>.†</s>"},"G3671":{"l":"ὁμολογία","o":6,"ar":"<f><o>ὁμολογία</o>، <g>-ας, ἡ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>اتفاق</b>، <b>موافقة</b>، <b>عهد</b>.</s> <s n=\"2.\"><b>اعتراف</b> (ربما دائمًا بالمعنى الموضوعي): <r v=\"2Cor.9.13\"></r>، <r v=\"1Tim.6.12\"></r>، <r v=\"1Tim.6.13\"></r>، <r v=\"Heb.3.1\"></r> <r v=\"Heb.4.14\"></r> <r v=\"Heb.10.13\"></r>.†</s>","en":"<f><o>ὁμολογία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>ὁμολογέω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Deut.12.6\"></r>, <r v=\"Deut.12.17\"></r>, <r v=\"Amos.4.5\"></r>, <r v=\"Ezek.46.12\"></r> (<h n=\"H5071\">נְדָבָה</h>), <r v=\"Lev.22.18\"></r>, <r v=\"Jer.44.25\"></r> (<h n=\"H5088\">נֶדֶר</h>), <r v=\"1Esd.9.8\"></r>*;]</e> </et> <s n=\"1.\">in cl., <b>an agreement</b>, <b>assent</b>, <b>compact</b> (in <g>π.</g>, of a contract; Deiss., <i>BS</i>, 249).</s> <s n=\"2.\"><b>confession</b> (prob. always in an objective sense): <r v=\"2Cor.9.13\"></r>, <r v=\"1Tim.6.12\"></r>, <r v=\"1Tim.6.13\"></r>, <r v=\"Heb.3.1\"></r> <r v=\"Heb.4.14\"></r> <r v=\"Heb.10.13\"></r>.†</s>"},"G3670":{"l":"ὁμολογέω","o":26,"ar":"<f><o>ὁμολογέω</o>، <g>-ῶ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>يتكلم اللغة نفسها</b>.</s> <s n=\"2.\">في اليونانية الكلاسيكية: <b>يتفق مع</b>.</s> <s n=\"3.\"><b>يوافق</b>، <b>يعترف</b>، <b>يُقِرّ</b>: مطلقًا، <r v=\"John.1.20\"></r> <r v=\"John.12.42\"></r>؛ المبني للمجهول، <r v=\"Rom.10.10\"></r>؛ يليه <g>ὅτι</g>، <r v=\"Rom.10.10\"></r>، <r v=\"Heb.11.13\"></r>؛ مع منصوب الشيء، <r v=\"Acts.23.8\"></r>، <r v=\"1John.1.9\"></r>، <r v=\"Rev.3.5\"></r>؛ والاستعمال نفسه مع قابل الشخص، <r v=\"Acts.24.14\"></r>؛ مع منصوب من لفظ الفعل («اعترف الاعتراف»)، <r v=\"1Tim.6.12\"></r>؛ مع منصوب الشخص، <r v=\"1John.2.23\"></r> <r v=\"1John.4.3\"></r>؛ والاستعمال نفسه يليه منصوب خبري، <r v=\"John.9.22\"></r>، <r v=\"Rom.10.9\"></r>، <r v=\"1John.4.2\"></r>، <r v=\"1John.4.15\"></r>، <r v=\"2John.1.7\"></r>؛ مع المصدر، <r v=\"Titus.1.16\"></r>؛ مع قابل الشخص يليه <g>ὅτι</g>، <r v=\"Matt.7.23\"></r>؛ يليه <g>ἐν</g> مع قابل الشخص (يعترف بـ)، <r v=\"Matt.10.32\"></r>، <r v=\"Luke.12.8\"></r>.</s> <s n=\"4.\"><b>يتعهد</b>، <b>يَعِد</b>: <g>τ. ἐπαγγελίαν</g>، <r v=\"Acts.7.17\"></r>؛ مع مصدر مفعولاً به، <r v=\"Matt.14.7\"></r>.</s> <s n=\"5.\">= <g>ἐξμολογέω</g>، <b>يحمد، يسبّح</b>: <r v=\"Heb.13.15\"></r>. (قارن <g>ἀνθ-ομολογέομοι</g>، <g>ἐξομολογέω</g>.)†</s>","en":"<f><o>ὁμολογέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>ὁμόλογος</g>, <i>of one mind</i>: <r v=\"Sus.1.60\"></r>*),</e> <e t=\"septuagint\">[in LXX: <r v=\"Job.40.9\"></r> (<r v=\"Job.40.14\"></r>) (<h n=\"H3034\">ידה</h> hi.), <r v=\"Jer.44.25\"></r> (<h n=\"H5087\">נדר</h>), al.;]</e> </et> <s n=\"1.\"><b>to speak the same language</b> (Hdt.).</s> <s n=\"2.\"><b>to agree with</b> (Hdt., Plat., al.).</s> <s n=\"3.\"><b>to agree</b>, <b>confess</b>, <b>acknowledge</b> (Plat., al.): absol., <r v=\"John.1.20\"></r> <r v=\"John.12.42\"></r>; pass., <r v=\"Rom.10.10\"></r>; seq. <g>ὅτι</g>, <r v=\"Rom.10.10\"></r>, <r v=\"Heb.11.13\"></r>; c. acc. rei, <r v=\"Acts.23.8\"></r>, <r v=\"1John.1.9\"></r>, <r v=\"Rev.3.5\"></r>; id. c. dat. pers., <r v=\"Acts.24.14\"></r>; c. acc. cogn., <r v=\"1Tim.6.12\"></r>; c. acc. pers., <r v=\"1John.2.23\"></r> <r v=\"1John.4.3\"></r>; id. seq. pred. acc. (Bl., § 34, 5; 73, 5), <r v=\"John.9.22\"></r>, <r v=\"Rom.10.9\"></r>, <r v=\"1John.4.2\"></r>, <r v=\"1John.4.15\"></r>, <r v=\"2John.1.7\"></r>; c. inf. (M, <i>Pr.</i>, 229), <r v=\"Titus.1.16\"></r>; c. dat. pers. seq. <g>ὅτι</g>, <r v=\"Matt.7.23\"></r>; seq. <g>ἐν</g>, c. dat. pers. (M, <i>Pr.</i>, 104; Bl., § 41, 2), <r v=\"Matt.10.32\"></r>, <r v=\"Luke.12.8\"></r>.</s> <s n=\"4.\"><b>to agree</b>, <b>promise</b>: <g>τ. ἐπαγγελίαν</g>, <r v=\"Acts.7.17\"></r>; c. inf. obj. (Bl., § 61, 3), <r v=\"Matt.14.7\"></r>.</s> <s n=\"5.\">= <g>ἐξμολογέω</g>, <b>to praise</b>: <r v=\"Heb.13.15\"></r> (Westc., in l.). (Cf. <g>ἀνθ-ομολογέομοι</g>, <g>ἐξομολογέω</g>.)†</s>"},"G3625":{"l":"οἰκουμένη","o":15,"ar":"<f><o>οἰκουμένη</o>، <g>-ης, ἡ</g></f> <s><b>الأرض المسكونة</b>؛ <s n=\"(a)\">في اليونانية الكلاسيكية: البلاد التي يسكنها اليونانيون، تمييزًا لها عن بلاد البرابرة؛</s> <s n=\"(b)\">عند الكتّاب المتأخرين: العالم الروماني: <r v=\"Luke.2.1\"></r>، <r v=\"Acts.11.28\"></r>، <r v=\"Acts.24.5\"></r>؛ وكنايةً عن سكانه: <r v=\"Acts.17.6\"></r>، <r v=\"Acts.19.27\"></r>؛</s> <s n=\"(c)\">في السبعينية (<r v=\"Ps.23.1\"></r>، <r v=\"Ps.71.8\"></r>، وفي مواضع أخرى) والعهد الجديد، أيضًا عن العالم المسكون كله: <r v=\"Matt.24.14\"></r>، <r v=\"Luke.4.5\"></r>، <r v=\"Luke.21.26\"></r>، <r v=\"Rom.10.18\"></r>، <r v=\"Heb.1.6\"></r>، <r v=\"Rev.3.10\"></r>، <r v=\"Rev.16.14\"></r>؛ وكنايةً (كما سبق)، <r v=\"Acts.17.31\"></r>، <r v=\"Rev.12.9\"></r>؛</s> <s n=\"(d)\">عن العصر المسياني، <g>ἡ οἰ. ἡ μέλλουσα</g> = <g>ὁ αἰὼ ὁ μέλλων</g>: <r v=\"Heb.2.5\"></r>.†</s> </s>","en":"<f><o>οἰκουμένη</o>, <g>-ης, ἡ</g></f> <et> <e t=\"derivation\">(fem. pres. pass. ptcp. of <g>οἰκέω</g>; sc. <g>γῆ</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H8398\">תֵּבֵל</h>, <h n=\"H776\">אֶרֶץ</h>;]</e> </et> <s><b>the inhabited earth</b>; <s n=\"(a)\">in cl., the countries occupied by Greeks, as disting. from barbarian lands (Hdt., Dem., al.);</s> <s n=\"(b)\">in later writers, the Roman world: <r v=\"Luke.2.1\"></r>, <r v=\"Acts.11.28\"></r> <r v=\"Acts.24.5\"></r>; by meton., of its inhabitants: <r v=\"Acts.17.6\"></r> <r v=\"Acts.19.27\"></r>;</s> <s n=\"(c)\">in LXX (<r v=\"Ps.23.1\"></r> <r v=\"Ps.71.8\"></r>, al.) and NT, also of the whole inhabited world: <r v=\"Matt.24.14\"></r>, <r v=\"Luke.4.5\"></r> <r v=\"Luke.21.26\"></r>, <r v=\"Rom.10.18\"></r>, <r v=\"Heb.1.6\"></r>, <r v=\"Rev.3.10\"></r> <r v=\"Rev.16.14\"></r>; by meton. (ut supr.), <r v=\"Acts.17.31\"></r>, <r v=\"Rev.12.9\"></r>;</s> <s n=\"(d)\">of the Messianic age, <g>ἡ οἰ. ἡ μέλλουσα</g> = <g>ὁ αἰὼ ὁ μέλλων</g>: <r v=\"Heb.2.5\"></r>.†</s> </s>"},"G3628":{"l":"οἰκτιρμός","o":5,"ar":"<f><o>οἰκτιρμός</o>، <g>-οῦ, ὁ</g></f> <s><b>رأفة</b>، <b>شفقة</b>: <g>σπλάγχνα οἰκτιρμοῦ</g>: <b>قلب رأفة</b>، <r v=\"Col.3.12\"></r>؛ في الجمع (كما في السبعينية ترجمةً للعبرية <h n=\"H7356\">רַחֲמִים</h>)، <g>οἰ. τ. θεοῦ</g>، <r v=\"Rom.12.1\"></r>، <r v=\"Heb.10.28\"></r>؛ <g>ὁ πατὴρ τῶν οἰ</g>، <r v=\"2Cor.1.3\"></r>؛ <g>σπλάγχνα κ. οἰ.</g>، <r v=\"Phil.2.1\"></r>.†</s>","en":"<f><o>οἰκτιρμός</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>οἰκτείρω</g>),</e> <e t=\"septuagint\">[in LXX, usually in pl., chiefly for <h n=\"H7356\">רַחַם</h>;]</e> </et> <s><b>compassion</b>, <b>pity</b>: <g>σπλάγχνα οἰκτιρμοῦ</g>, <b>a heart of compassion</b>, <r v=\"Col.3.12\"></r>; in pl. (as LXX for Heb. <h n=\"H7356\">רַחֲמִים</h>), <g>οἰ. τ. θεοῦ</g>, <r v=\"Rom.12.1\"></r>, <r v=\"Heb.10.28\"></r>; <g>ὁ πατὴρ τῶν οἰ</g>, <r v=\"2Cor.1.3\"></r>; <g>σπλάγχνα κ. οἰ.</g>, <r v=\"Phil.2.1\"></r>.†</s> <sy><i>SYN.</i>: <g>ἔλεος</g>, q.v.</sy>"},"G3616":{"l":"οἰκοδεσποτέω","o":1,"ar":"<f><o>οἰκο-δεσποτέω</o>، <g>-ῶ</g></f> <s><b>يدبّر البيت</b>: <r v=\"1Tim.5.14\"></r>.†</s>","en":"<f><o>οἰκο-δεσποτέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>οἰκοδεσπότης</g>),</e> </et> <s><b>to rule a household</b>: <r v=\"1Tim.5.14\"></r>.†</s>"},"G3618":{"l":"οἰκοδομέω","o":40,"ar":"<f><o>οἰκοδομέω</o>، <g>-ῶ</g></f> <s><b>يبني بيتًا</b>، <b>يبني</b>: مطلقًا، <r v=\"Luke.11.48\"></r> <r v=\"Luke.14.30\"></r> <r v=\"Luke.17.28\"></r>؛ <g>οἱ οἰκοδομοῦντες</g>، <b>البنّاؤون</b> (مثل <r v=\"Ps.118.22\"></r>، <h n=\"H1129\">הַבּוֹנִים</h>)، <r v=\"Matt.21.42\"></r>، <r v=\"Mark.12.10\"></r>، <r v=\"Luke.20.17\"></r>، <r v=\"1Pet.2.7\"></r><i>(السبعينية)</i>؛ <g>ἐπ’ ἀλλότριον θεμέλιον οἰ.</g>، في قول سائر، <r v=\"Rom.15.20\"></r>؛ مع المنصوب للشيء، <r v=\"Gal.2.18\"></r>؛ <g>πύργον</g>، <r v=\"Matt.21.33\"></r>، <r v=\"Mark.12.1\"></r>، <r v=\"Luke.14.28\"></r>؛ <g>ἀποθήκας</g>، <r v=\"Luke.12.18\"></r>؛ <g>ναόν</g>، <r v=\"Mark.14.58\"></r>؛ المبني للمجهول، <r v=\"John.2.20\"></r>؛ <g>οἰκία</g>، <r v=\"Luke.6.48\"></r>؛ مع المنصوب للشيء يليه القابل للشخص (قارن <r v=\"Gen.8.20\"></r>، <r v=\"Ezek.16.24\"></r>)، <r v=\"Luke.7.5\"></r>، <r v=\"Acts.7.47\"></r>، <r v=\"Acts.7.49\"></r>؛ المنصوب يليه <g>ἐπί</g>، <r v=\"Matt.7.24\"></r>، <r v=\"Matt.7.26\"></r> <r v=\"Luke.6.49\"></r>؛ <g>πόλιν ἐπ’ ὄρους</g>، <r v=\"Luke.4.29\"></r>؛ عن إعادة البناء أو الترميم، <r v=\"Matt.23.29\"></r> <r v=\"Matt.26.61\"></r> <r v=\"Matt.27.40\"></r>، <r v=\"Mark.15.29\"></r>، <r v=\"Luke.11.47\"></r>. مجازيًا، <g>τ. ἐκκλησίαν</g>، <r v=\"Matt.16.18\"></r>؛ عن نموّ الشخصية المسيحية (قارن <h n=\"H1129\">בּנה</h> في <r v=\"Ps.28.5\"></r>، <r v=\"Jer.24.6\"></r>، وفي مواضع أخرى)، <b>يبني</b> (الترجمة المعتمدة: <b>يبني روحيًا</b>): مطلقًا، <r v=\"Acts.20.32\"></r>، <r v=\"1Cor.8.1\"></r> <r v=\"1Cor.10.23\"></r>؛ مع المنصوب للشخص، <r v=\"1Cor.14.4\"></r>، <r v=\"1Thess.5.11\"></r>؛ المبني للمجهول، <r v=\"Acts.9.31\"></r>، <r v=\"1Cor.14.17\"></r>، <r v=\"1Pet.2.5\"></r>؛ عن فعل مذموم (الترجمة المعتمدة: <i>يُجرِّئ</i>)، <r v=\"1Cor.8.10\"></r> (قارن <g>ἀν-</g>، <g>ἐπ-</g>، <g>συν-οικοδομέω</g>).†</s>","en":"<f><o>οἰκοδομέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>οἰκοδόμος</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1129\">בּנה</h>;]</e> </et> <s><b>to build a house</b>, <b>to build</b>: absol., <r v=\"Luke.11.48\"></r> <r v=\"Luke.14.30\"></r> <r v=\"Luke.17.28\"></r>; <g>οἱ οἰκοδομοῦντες</g>, <b>the builders</b> (as <r v=\"Ps.118.22\"></r>, <h n=\"H1129\">הַבּוֹנִים</h>), <r v=\"Matt.21.42\"></r>, <r v=\"Mark.12.10\"></r>, <r v=\"Luke.20.17\"></r>, <r v=\"1Pet.2.7\"></r><i>(LXX)</i>; <g>ἐπ’ ἀλλότριον θεμέλιον οἰ.</g>, proverb., <r v=\"Rom.15.20\"></r>; c. acc. rei, <r v=\"Gal.2.18\"></r>; <g>πύργον</g>, <r v=\"Matt.21.33\"></r>, <r v=\"Mark.12.1\"></r>, <r v=\"Luke.14.28\"></r>; <g>ἀποθήκας</g>, <r v=\"Luke.12.18\"></r>; <g>ναόν</g>, <r v=\"Mark.14.58\"></r>; pass., <r v=\"John.2.20\"></r>; <g>οἰκία</g>, <r v=\"Luke.6.48\"></r>; c. acc. rei seq. dat. pers. (cf. <r v=\"Gen.8.20\"></r>, <r v=\"Ezek.16.24\"></r>), <r v=\"Luke.7.5\"></r>, <r v=\"Acts.7.47\"></r>, <r v=\"Acts.7.49\"></r>; acc. seq. <g>ἐπί</g>, <r v=\"Matt.7.24\"></r>, <r v=\"Matt.7.26\"></r> <r v=\"Luke.6.49\"></r>; <g>πόλιν ἐπ’ ὄρους</g>, <r v=\"Luke.4.29\"></r>; of rebuilding, or restoring, <r v=\"Matt.23.29\"></r> <r v=\"Matt.26.61\"></r> <r v=\"Matt.27.40\"></r>, <r v=\"Mark.15.29\"></r>, <r v=\"Luke.11.47\"></r>. Metaph., <g>τ. ἐκκλησίαν</g>, <r v=\"Matt.16.18\"></r>; of the growth of Christian character (cf. <h n=\"H1129\">בּנה</h>, in <r v=\"Ps.28.5\"></r>, <r v=\"Jer.24.6\"></r>, al.), <b>to build up</b> (AV, <b>edify</b>): absol., <r v=\"Acts.20.32\"></r>, <r v=\"1Cor.8.1\"></r> <r v=\"1Cor.10.23\"></r>; c. acc. pers., <r v=\"1Cor.14.4\"></r>, <r v=\"1Thess.5.11\"></r>; pass., <r v=\"Acts.9.31\"></r>, <r v=\"1Cor.14.17\"></r>, <r v=\"1Pet.2.5\"></r>; of blameworthy action (AV, <i>embolden</i>), <r v=\"1Cor.8.10\"></r> (cf. <g>ἀν-</g>, <g>ἐπ-</g>, <g>συν-οικοδομέω</g>).†</s>"},"G3633":{"l":"οἴομαι","o":3,"ar":"<f><o>οἴομαι</o>، <g>οἶμαι</g>،</f> <s><b>يظنّ</b>، <b>يتوقّع</b>، <b>يتصوّر</b>؛ مع المنصوب والمصدر، <r v=\"John.21.25\"></r>؛ مع المصدر، <r v=\"Phil.1.17\"></r>؛ يليه <g>ὅτι</g>، <r v=\"Jas.1.7\"></r>.†</s>","en":"<f><o>οἴομαι</o>, <g>οἶμαι</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H2009\">הִנֵּה</h>, <r v=\"Gen.37.7\"></r>, al.;]</e> </et> <s><b>to suppose</b>, <b>expect</b>, <b>imagine</b>; c. acc. et inf., <r v=\"John.21.25\"></r>; c. inf., <r v=\"Phil.1.17\"></r>; seq. <g>ὅτι</g>, <r v=\"Jas.1.7\"></r>.†</s> <sy><i>SYN.</i>: v.s. <g>ἡγέομαι</g>.</sy>"},"G3694":{"l":"ὀπίσω","o":35,"ar":"<f><o>ὀπίσω</o>،</f> ظرف مكان وزمان، <s n=\"1.\">بالمعنى الأصلي، ظرفًا: <s n=\"(a)\">عن الزمان (لا يرد في العهد الجديد)؛</s> <s n=\"(b)\">عن المكان: <b>إلى الوراء</b>، <b>خلف</b>، <b>بعد</b>: <r v=\"Matt.24.18\"></r>، <r v=\"Luke.7.38\"></r>؛ <g>τὰ ὀ.</g>، <r v=\"Phil.3.13\"></r>؛ <g>εἰς τὰ ὀ.</g>، <r v=\"Mark.13.16\"></r>، <r v=\"Luke.9.62\"></r> <r v=\"Luke.17.31\"></r>، <r v=\"John.6.66\"></r> <r v=\"John.18.6\"></r> <r v=\"John.20.14\"></r>.</s> </s> <s n=\"2.\">باستعمال لا يوجد في الكلاسيكية، وفي السبعينية مقابلاً لحرف الجر العبري <h n=\"H310\">אַחֲרֵי</h>، لكنه على الأرجح شائع أيضًا في اللغة الدارجة: حرفَ جر مع المضاف إليه؛ <s n=\"(a)\">عن الزمان: <b>بعد</b>: <r v=\"Matt.3.11\"></r>، <r v=\"Mark.1.7\"></r>، <r v=\"John.1.15\"></r>، <r v=\"John.1.27\"></r>، <r v=\"John.1.30\"></r>؛</s> <s n=\"(b)\">عن المكان: <b>خلف</b>، <b>وراء</b>: <r v=\"Matt.4.19\"></r> <r v=\"Matt.10.38\"></r> <r v=\"Matt.16.23\"></r>، <r v=\"Matt.16.24\"></r>، <r v=\"Mark.1.17\"></r>، <r v=\"Mark.1.20\"></r> <r v=\"Mark.8.33\"></r>، <r v=\"Mark.8.34\"></r>، <r v=\"Luke.9.23\"></r> <r v=\"Luke.14.27\"></r> <r v=\"Luke.19.14\"></r> <r v=\"Luke.21.8\"></r>، <r v=\"2Pet.2.10\"></r>، <r v=\"Jude.1.7\"></r>، <r v=\"Rev.1.10\"></r> <r v=\"Rev.12.15\"></r>؛ في تركيب مُضمَّن المعنى (قارن <r v=\"Rev.13.3\"></r>)، <r v=\"John.12.19\"></r>، <r v=\"Acts.5.17\"></r> <r v=\"Acts.20.30\"></r>، <r v=\"1Tim.5.15\"></r>، <r v=\"Rev.13.3\"></r>.†</s> </s>","en":"<f><o>ὀπίσω</o>,</f> adv. of place and time, <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H310\">אַחֲרֵי</h>, <h n=\"H310\">אַחַר</h> and cogn. forms;]</e> </et> <s n=\"1.\">prop., as in cl., adv., <s n=\"(a)\">of time (not in NT);</s> <s n=\"(b)\">of place, <b>back</b>, <b>behind</b>, <b>after</b>: <r v=\"Matt.24.18\"></r>, <r v=\"Luke.7.38\"></r>; <g>τὰ ὀ.</g>, <r v=\"Phil.3.13\"></r>; <g>εἰς τὰ ὀ.</g>, <r v=\"Mark.13.16\"></r>, <r v=\"Luke.9.62\"></r> <r v=\"Luke.17.31\"></r>, <r v=\"John.6.66\"></r> <r v=\"John.18.6\"></r> <r v=\"John.20.14\"></r>.</s> </s> <s n=\"2.\">By a usage not found in cl., and in LXX representing the Heb. prep. <h n=\"H310\">אַחֲרֵי</h> (Bl., § 40, 8; Thackeray, <i>Gr.</i>, 46 f.), but also prob. general in vernacular (M, <i>Pr.</i>, 99), as prep. c. gen.; <s n=\"(a)\">of time, <b>after</b>: <r v=\"Matt.3.11\"></r>, <r v=\"Mark.1.7\"></r>, <r v=\"John.1.15\"></r>, <r v=\"John.1.27\"></r>, <r v=\"John.1.30\"></r>;</s> <s n=\"(b)\">of place, <b>behind</b>, <b>after</b>: <r v=\"Matt.4.19\"></r> <r v=\"Matt.10.38\"></r> <r v=\"Matt.16.23\"></r>, <r v=\"Matt.16.24\"></r>, <r v=\"Mark.1.17\"></r>, <r v=\"Mark.1.20\"></r> <r v=\"Mark.8.33\"></r>, <r v=\"Mark.8.34\"></r>, <r v=\"Luke.9.23\"></r> <r v=\"Luke.14.27\"></r> <r v=\"Luke.19.14\"></r> <r v=\"Luke.21.8\"></r>, <r v=\"2Pet.2.10\"></r>, <r v=\"Jude.1.7\"></r>, <r v=\"Rev.1.10\"></r> <r v=\"Rev.12.15\"></r>; in constr. praegn. (v. Swete on <r v=\"Rev.13.3\"></r>), <r v=\"John.12.19\"></r>, <r v=\"Acts.5.17\"></r> <r v=\"Acts.20.30\"></r>, <r v=\"1Tim.5.15\"></r>, <r v=\"Rev.13.3\"></r>.†</s> </s>"},"G3664":{"l":"ὅμοιος","o":45,"ar":"<f><o>ὅμοιος</o>، <g>-οία, -οιον</g>،</f> <s><b>مثل</b>، <b>شبيه</b>، <b>نظير</b>، <b>مماثل</b>: مع القابل، عن الشكل أو المنظر، <r v=\"John.9.9\"></r>، <r v=\"Rev.1.13\"></r> <r v=\"Rev.1.15\"></r> <r v=\"Rev.2.18\"></r> <r v=\"Rev.4.6\"></r>، <r v=\"Rev.4.7\"></r> <r v=\"Rev.9.7\"></r>، <r v=\"Rev.9.10\"></r> <r v=\"Rev.9.19\"></r> <r v=\"Rev.11.1\"></r> <r v=\"Rev.13.2\"></r>، <r v=\"Rev.13.11\"></r>؛ <g>ὁράσει</g>، <r v=\"Rev.4.3\"></r>؛ عن الطبيعة والحالة والقدرة ونحوها، <r v=\"Matt.22.39\"></r>، <r v=\"Acts.17.29\"></r>، <r v=\"Gal.5.21\"></r>، <r v=\"1John.3.2\"></r>، <r v=\"Rev.13.4\"></r> <r v=\"Rev.18.18\"></r> <r v=\"Rev.21.11\"></r>، <r v=\"Rev.21.18\"></r>؛ للمقارنة في الأمثال، <r v=\"Matt.13.31\"></r> وما يليه <r v=\"Matt.20.1\"></r>، <r v=\"Luke.13.18\"></r>، <r v=\"Luke.13.19\"></r>، <r v=\"Luke.13.21\"></r>؛ عن التفكير والعمل ونحوهما، <r v=\"Matt.11.16\"></r> <r v=\"Matt.13.52\"></r>، <r v=\"Luke.6.47-Luke.6.49\"></r> <r v=\"Luke.7.31\"></r>، <r v=\"Luke.7.32\"></r> <r v=\"Luke.12.36\"></r>، <r v=\"John.8.55\"></r>، <r v=\"Jude.1.7\"></r>؛ مع المنصوب، <r v=\"Rev.1.13\"></r> <r v=\"Rev.14.14\"></r>.†</s>","en":"<f><o>ὅμοιος</o>, <g>-οία, -οιον</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H3644\">כָּמוֹ</h>, etc.;]</e> </et> <s><b>like</b>, <b>resembling</b>, <b>such as</b>, <b>the same as</b>: c. dat., of form or appearance, <r v=\"John.9.9\"></r>, <r v=\"Rev.1.13\"></r> (WH, mg., R, but v. infr.) <r v=\"Rev.1.15\"></r> <r v=\"Rev.2.18\"></r> <r v=\"Rev.4.6\"></r>, <r v=\"Rev.4.7\"></r> <r v=\"Rev.9.7\"></r>, <r v=\"Rev.9.10\"></r> (Bl., § 37, 6<i>2</i>) <r v=\"Rev.9.19\"></r> <r v=\"Rev.11.1\"></r> <r v=\"Rev.13.2\"></r>, <r v=\"Rev.13.11\"></r>; <g>ὁράσει</g>, <r v=\"Rev.4.3\"></r>; of nature, condition, ability, etc., <r v=\"Matt.22.39\"></r>, <r v=\"Acts.17.29\"></r>, <r v=\"Gal.5.21\"></r>, <r v=\"1John.3.2\"></r>, <r v=\"Rev.13.4\"></r> <r v=\"Rev.18.18\"></r> <r v=\"Rev.21.11\"></r>, <r v=\"Rev.21.18\"></r>; of comparison in parables, <r v=\"Matt.13.31\"></r> ff. <r v=\"Matt.20.1\"></r>, <r v=\"Luke.13.18\"></r>, <r v=\"Luke.13.19\"></r>, <r v=\"Luke.13.21\"></r>; of thinking, acting, etc., <r v=\"Matt.11.16\"></r> <r v=\"Matt.13.52\"></r>, <r v=\"Luke.6.47-Luke.6.49\"></r> <r v=\"Luke.7.31\"></r>, <r v=\"Luke.7.32\"></r> (T, c. gen.; Bl., § 36, 11) <r v=\"Luke.12.36\"></r>, <r v=\"John.8.55\"></r>, <r v=\"Jude.1.7\"></r>; c. acc., <r v=\"Rev.1.13\"></r> (WH, txt.; Swete, Hort, in l.) <r v=\"Rev.14.14\"></r>.†</s>"},"G3614":{"l":"οἰκία","o":93,"ar":"<f><o>οἰκία</o>، <g>-ας, ἡ</g></f> <s><b>بيت</b>، <b>مسكن</b>: <r v=\"Matt.2.11\"></r> <r v=\"Matt.7.24-Matt.7.27\"></r>، <r v=\"Mark.1.29\"></r>، وفي مواضع أخرى؛ <g>ἐν οἰκίᾳ</g> (= <g>κατ ̓ οἰκίαν</g> في الكلاسيكية)، <b>في البيت</b>، <r v=\"Luke.8.27\"></r>؛ <g>εἰς οἰ.</g>، <r v=\"2John.1.10\"></r>؛ <g>οἰ</g> مع المضاف إليه للشخص تأتي عادةً بأداة التعريف (<r v=\"Matt.8.14\"></r>، وفي مواضع أخرى، لكن قارن <g>οἶκος</g>)؛ <g>ἡ οἰ. τ. πατρός μου</g>، <r v=\"John.14.2\"></r>. مجازيًا، <s n=\"(a)\">عن الجسد بوصفه مسكن النفس: <r v=\"2Cor.5.1\"></r>؛ </s> <s n=\"(b)\">عن الممتلكات (مثل <h n=\"H1004\">בַּיִת</h>، <r v=\"Gen.45.18\"></r>، السبعينية <g>τ. ὑπάρχοντα</g>؛ <r v=\"1Kgs.13.8\"></r>، السبعينية <g>οἶκος</g>) = <g>οἶκος</g> (انظره): <r v=\"Mark.12.40\"></r>، <r v=\"Luke.20.47\"></r>؛</s> <s n=\"(c)\">عن ساكني البيت، <b>أهل البيت</b>: <r v=\"Matt.12.25\"></r>؛ مع المضاف إليه للشخص، <r v=\"John.4.53\"></r>، <r v=\"1Cor.16.15\"></r>.</s> </s>","en":"<f><o>οἰκία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>οἶκος</g>),</e> <e t=\"septuagint\">[in LXX chiefly (very freq.) for <h n=\"H1004\">בַּיִת</h>;]</e> </et> <s><b>a house</b>, <b>dwelling</b>: <r v=\"Matt.2.11\"></r> <r v=\"Matt.7.24-Matt.7.27\"></r>, <r v=\"Mark.1.29\"></r>, al.; <g>ἐν οἰκίᾳ</g> (= cl. <g>κατ ̓ οἰκίαν</g>), <b>at home</b>, <r v=\"Luke.8.27\"></r>; <g>εἰς οἰ.</g>, <r v=\"2John.1.10\"></r>; <g>οἰ</g>, c. gen. pers., usually has the art. (<r v=\"Matt.8.14\"></r>, al., but cf. <g>οἶκος</g> and v. Bl., § 46, 9); <g>ἡ οἰ. τ. πατρός μου</g>, <r v=\"John.14.2\"></r>. Metaph., <s n=\"(a)\">of the body as the dwelling of the soul: <r v=\"2Cor.5.1\"></r>; </s> <s n=\"(b)\">of property (as <h n=\"H1004\">בַּיִת</h>, <r v=\"Gen.45.18\"></r>, LXX, <g>τ. ὑπάρχοντα</g>; <r v=\"1Kgs.13.8\"></r>, LXX, <g>οἶκος</g>) = <g>οἶκος</g> (q.v.): <r v=\"Mark.12.40\"></r>, <r v=\"Luke.20.47\"></r>;</s> <s n=\"(c)\">of the inmates of the dwelling, <b>the household</b>: <r v=\"Matt.12.25\"></r>; c. gen. pers., <r v=\"John.4.53\"></r>, <r v=\"1Cor.16.15\"></r>.</s> </s> <sy><i>SYN.</i>: <g>οἶκος</g>, which in Attic law denoted the whole <i>estate</i>, <g>οἰκία</g>, the <i>dwelling</i> only. In cl. poets <g>οἶκος</g> has also the latter sense, but not in prose, except in metaph. usage, where it signifies both <i>property</i> and <i>household</i>. The foregoing distinction is not, however, consistently maintained in late Greek; cf. MM, ii, xvii, and v. Thayer, s.v. <g>οἰκία</g>.</sy>"},"G3689":{"l":"ὄντως","o":10,"ar":"<f><o>ὄντως</o>،</f> ظرف <s><b>حقًّا</b>، <b>بالحقيقة</b>، <b>فعلاً</b>: <r v=\"Mark.11.32\"></r>، <r v=\"Luke.23.47\"></r> <r v=\"Luke.24.34\"></r>، <r v=\"John.8.36\"></r>، <r v=\"1Cor.14.25\"></r>، <r v=\"Gal.3.21\"></r>؛ <g>ἡ ὄ. ζωή</g>، <r v=\"1Tim.6.19\"></r>؛ <g>ἡ ὄ. χήρα</g>، <r v=\"1Tim.5.3\"></r>، <r v=\"1Tim.5.5\"></r>، <r v=\"1Tim.5.16\"></r>.†</s>","en":"<f><o>ὄντως</o>,</f> adv. <et> <e t=\"derivation\">(&lt; <g>ὤν</g>, ptcp. of <g>εἰμί</g>, <i>sum</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Num.22.37\"></r> (<h n=\"H551\">אֻמְנָם</h>), <r v=\"Jer.3.23\"></r> (<h n=\"H403\">אָכֵן</h>), <r v=\"Jer.10.19\"></r> (<h n=\"H389\">אַךְ</h>), <r v=\"1Kgs.12.24\"></r>, <r v=\"Wis.17.14\"></r>*;]</e> </et> <s><b>really</b>, <b>actually</b>, <b>truly</b>: <r v=\"Mark.11.32\"></r>, <r v=\"Luke.23.47\"></r> <r v=\"Luke.24.34\"></r>, <r v=\"John.8.36\"></r>, <r v=\"1Cor.14.25\"></r>, <r v=\"Gal.3.21\"></r>; <g>ἡ ὄ. ζωή</g>, <r v=\"1Tim.6.19\"></r>; <g>ἡ ὄ. χήρα</g>, <r v=\"1Tim.5.3\"></r>, <r v=\"1Tim.5.5\"></r>, <r v=\"1Tim.5.16\"></r>.†</s>"},"G3626":{"l":"οἰκουρός","o":1,"ar":"<f>* <o>οἰκ-ουρός</o>، <g>-ον</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>حارس البيت</b> أو <b>حافظه</b>؛ وبمعنى الاسم <g>ἡ οἰ.</g>: <b>مدبّرة المنزل</b>.</s> <s n=\"2.\"><b>ملازم للبيت</b>: <r v=\"Titus.2.5\"></r> (قارن <g>οἰκουργός</g>).†</s>","en":"<f>* <o>οἰκ-ουρός</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>οἶκος</g> + <g>οὖρος</g>, <i>a keeper</i>);</e> </et> <s n=\"1.\"><b>watching</b> or <b>keeping the house</b>; as subst., <g>ἡ οἰ.</g>, <b>a housekeeper</b> (Soph., Eur.; v. LS, s.v.).</s> <s n=\"2.\"><b>keeping at home</b>: <r v=\"Titus.2.5\"></r>, Rec. (v. Field, <i>Notes</i>, 220 ff.; <i>CGT</i>, in l., and cf. <g>οἰκουργός</g>).†</s>"},"G3634":{"l":"οἷος","o":14,"ar":"<f><o>οἷος</o>، <g>-α, -ον</g>،</f> ضمير موصول، <s>للنوع (علاقته بـ <g>ὅς</g> كعلاقة <l>qualis</l> بـ <l>qui</l>)، <b>أيّ نوع</b> أو <b>أيّ صنف من</b>، <b>مثل</b>، وفي العهد الجديد عادةً بدون مقابِله <g>τοιοῦτος</g>: <r v=\"Matt.24.21\"></r>، <r v=\"Mark.9.3\"></r>، <r v=\"2Cor.12.20\"></r>، <r v=\"1Thess.1.5\"></r>، <r v=\"2Tim.3.11\"></r>، <r v=\"Rev.16.18\"></r>؛ يليه <g>τοιοῦτος</g>، <r v=\"1Cor.15.48\"></r>، <r v=\"2Cor.10.11\"></r>؛ ونفسه زائدًا، <r v=\"Mark.13.19\"></r>؛ <g>τ. αὐτὸν . . . σἷον</g>، <r v=\"Phil.1.30\"></r>؛ <g>οὐχ οἷον δὲ ὅτι</g> على الحذف: <b>ولكن ليس كأنّ</b>، <r v=\"Rom.9.6\"></r>.†</s>","en":"<f><o>οἷος</o>, <g>-α, -ον</g>,</f> relat. pron., <s>qualitative (related to <g>ὅς</g> as <l>qualis</l> to <l>qui</l>), <b>what sort</b> or <b>manner of</b>, <b>such as</b>, in NT usually without its correl. <g>τοιοῦτος</g>: <r v=\"Matt.24.21\"></r>, <r v=\"Mark.9.3\"></r>, <r v=\"2Cor.12.20\"></r>, <r v=\"1Thess.1.5\"></r>, <r v=\"2Tim.3.11\"></r>, <r v=\"Rev.16.18\"></r>; seq. <g>τοιοῦτος</g>, <r v=\"1Cor.15.48\"></r>, <r v=\"2Cor.10.11\"></r>; id. redundant, <r v=\"Mark.13.19\"></r>; <g>τ. αὐτὸν . . . σἷον</g>, <r v=\"Phil.1.30\"></r>; <g>οὐχ οἷον δὲ ὅτι</g>, elliptically, <b>but</b> it is <b>not as though</b> (RV), <r v=\"Rom.9.6\"></r>.†</s>"},"G3668":{"l":"ὁμοίως","o":30,"ar":"<f><o>ὁμοίως</o></f> ظرف، <s><b>كذلك</b>، <b>بالمثل</b>، <b>على حد سواء</b>: <r v=\"Matt.22.26\"></r>، <r v=\"Mark.4.16\"></r>، <r v=\"Luke.10.37\"></r>، وفي مواضع أخرى؛ مع القابل، <r v=\"Matt.22.39\"></r>، <r v=\"Luke.6.31\"></r>؛ <g>ὁ. καί</g>، <r v=\"Matt.22.26\"></r>، <r v=\"Mark.15.31\"></r>، وفي مواضع أخرى؛ <g>ὁ. καθώς</g>، <r v=\"Luke.17.28\"></r>؛ <g>καθὼς . . . ὁ.</g>، <r v=\"Luke.6.31\"></r>؛ <g>ὁ. μέντοι καί</g>، <r v=\"Jude.1.8\"></r>.</s>","en":"<f><o>ὁμοίως</o></f> <et> <e t=\"derivation\">(&lt; <g>ὅμοιος</g>),</e> </et> adv., <s><b>likewise</b>, <b>in like manner</b>, <b>equally</b>: <r v=\"Matt.22.26\"></r>, <r v=\"Mark.4.16\"></r>, <r v=\"Luke.10.37\"></r>, al.; c. dat., <r v=\"Matt.22.39\"></r>, <r v=\"Luke.6.31\"></r>; <g>ὁ. καί</g>, <r v=\"Matt.22.26\"></r>, <r v=\"Mark.15.31\"></r>, al.; <g>ὁ. καθώς</g>, <r v=\"Luke.17.28\"></r>; <g>καθὼς . . . ὁ.</g>, <r v=\"Luke.6.31\"></r>; <g>ὁ. μέντοι καί</g>, <r v=\"Jude.1.8\"></r>.</s>"},"G3636":{"l":"ὀκνηρός","o":3,"ar":"<f><o>ὀκνηρός</o>، <g>-ά, -όν</g></f> <s><b>متردّد</b>، <b>متقاعس</b>، <b>هيّاب</b>: مع القابل، <r v=\"Rom.12.11\"></r>؛ ومن ثمّ <b>كسلان، متكاسل</b>: <r v=\"Matt.25.26\"></r>. عن الأشياء: <b>ما يُثقل على النفس</b>، <b>شاقّ، ثقيل</b>: <r v=\"Phil.3.1\"></r>.†</s>","en":"<f><o>ὀκνηρός</o>, <g>-ά, -όν</g></f> <et> <e t=\"derivation\">(&lt; <g>ὀκνέω</g>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H6102\">עָצֵל</h> <r v=\"Prov.6.6\"></r>, <r v=\"Prov.6.9\"></r> al.;]</e> </et> <s><b>shrinking</b>, <b>hesitating</b>, <b>timid</b>: c. dat. (Bl., § 38, 2), <r v=\"Rom.12.11\"></r>; hence, <b>slothful</b>: <r v=\"Matt.25.26\"></r>. Of things, <b>that which causes shrinking</b>, <b>irksome</b>: <r v=\"Phil.3.1\"></r>.†</s>"},"G3654":{"l":"ὅλως","o":4,"ar":"<f><o>ὅλως</o>،</f> ظرف <s><b>على الإطلاق</b>، <b>يقينًا</b>، <b>فعلاً</b> (مع النفي: <i>البتّة</i>): <r v=\"Matt.5.34\"></r>، <r v=\"1Cor.5.1\"></r> <r v=\"1Cor.6.7\"></r> <r v=\"1Cor.15.29\"></r>.†</s>","en":"<f><o>ὅλως</o>,</f> adv. <et> <e t=\"derivation\">(&lt; <g>ὅλος</g>),</e> </et> <s><b>altogether</b>, <b>assuredly</b>, <b>actually</b> (c. neg., <i>at all</i>): <r v=\"Matt.5.34\"></r>, <r v=\"1Cor.5.1\"></r> <r v=\"1Cor.6.7\"></r> <r v=\"1Cor.15.29\"></r>.†</s>"},"G3651":{"l":"ὁλοτελής","o":1,"ar":"<f>*† <o>ὁλοτελής</o>، <g>-ές</g></f> <s><b>تامّ</b>، <b>كامل</b>: <r v=\"1Thess.5.23\"></r>.†</s>","en":"<f>*† <o>ὁλοτελής</o>, <g>-ές</g></f> <et> <e t=\"derivation\">(&lt; <g>ὅλος</g>, <g>τέλος</g>),</e> </et> <s><b>complete</b>, <b>perfect</b>: <r v=\"1Thess.5.23\"></r>.†</s> <sy><i>SYN.</i>: <g>ὁλόκληρος</g> (q.v.), <g>τέλειος</g>. \"As regards meaning, <g>ὁλόκληρος</g> can hardly be distinguished from <g>ὁλοτελής</g> though, in accordance with its derivation, it draws more special attention to the several parts to which the wholeness spoken of extends, no part being wanting or lacking in completeness\" (M, <i>Th.</i>, 78).</sy>"},"G3623":{"l":"οἰκονόμος","o":10,"ar":"<f><o>οἰκονόμος</o>، <g>-ου, ὁ</g></f> <s n=\"1.\">بالمعنى الأصلي، <b>مدبّر البيت</b> أو <b>الضيعة</b>، <b>وكيل البيت</b> أو <b>وكيل الأرض</b> (وكان عادةً عبدًا أو معتَقًا): <r v=\"Luke.12.42\"></r>، <r v=\"Luke.16.1\"></r>، <r v=\"Luke.16.3\"></r>، <r v=\"Luke.16.8\"></r>، <r v=\"1Cor.4.2\"></r>، <r v=\"Gal.4.2\"></r>؛ <g>ὀ οἰ. τ. πόλεως</g> (في الترجمة المنقحة: <i>الخازن</i>؛ قارن <r v=\"1Esd.4.49\"></r>)، <r v=\"Rom.16.23\"></r>.</s> <s n=\"2.\">مجازيًا (بمعنى أوسع؛ قارن <g>οἰκονομία</g>)، <b>مدبّر</b>، <b>وكيل</b>: عن خدام المسيحيين، <r v=\"1Cor.4.1\"></r>، <r v=\"Titus.1.7\"></r>؛ وعن المسيحيين عمومًا، <r v=\"1Pet.4.10\"></r>.†</s>","en":"<f><o>οἰκονόμος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>οἶκος</g> + <g>νέμω</g>, <i>to manage</i>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1004\">עַל־הַבַּיִת</h>;]</e> </et> <s n=\"1.\">prop., <b>the manager of a household</b> or <b>estate</b>, <b>a house-</b> or <b>land-steward</b> (usually a slave or freedman): <r v=\"Luke.12.42\"></r> <r v=\"Luke.16.1\"></r>, <r v=\"Luke.16.3\"></r>, <r v=\"Luke.16.8\"></r>, <r v=\"1Cor.4.2\"></r>, <r v=\"Gal.4.2\"></r>; <g>ὀ οἰ. τ. πόλεως</g> (RV, <i>treasurer</i>; cf. <r v=\"1Esd.4.49\"></r>), <r v=\"Rom.16.23\"></r>.</s> <s n=\"2.\">Metaph. (in wider sense; cf. <g>οἰκονομία</g>), <b>an administrator</b>, <b>a steward</b>: of Christian ministers, <r v=\"1Cor.4.1\"></r>, <r v=\"Titus.1.7\"></r>; of Christians generally, <r v=\"1Pet.4.10\"></r>.†</s>"},"G3667":{"l":"ὁμοίωμα","o":6,"ar":"<f><o>ὁμοίωμα</o>، <g>-τος, τό</g></f> <s><b>ما صُنع على شبه</b> شيء؛ <s n=\"(a)\">محسوسًا، <b>صورة</b>، <b>شبه</b> (<r v=\"Ps.106.20\"></r>، <r v=\"Ezek.1.5\"></r>، <r v=\"1Macc.3.48\"></r>، وفي مواضع أخرى): <r v=\"Rev.9.7\"></r>؛</s> <s n=\"(b)\">مجردًا، <b>شَبَه</b>، <b>مماثلة</b>: <r v=\"Rom.5.14\"></r>، <r v=\"Rom.6.5\"></r>، <r v=\"Rom.8.3\"></r>، <r v=\"Phil.2.7\"></r>؛ <g>ἐν ὁ. εἰκόνος</g>، <r v=\"Rom.1.23\"></r>.†</s> </s>","en":"<f><o>ὁμοίωμα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>ὁμοιόω</g>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H1823\">דְּמוּת</h>, <h n=\"H8403\">תַּבְנִית</h>, <h n=\"H8544\">תְּמוּנָה</h>, etc.;]</e> </et> <s><b>that which is made like</b> something; <s n=\"(a)\">concrete, <b>an image</b>, <b>likeness</b> (<r v=\"Ps.106.20\"></r>, <r v=\"Ezek.1.5\"></r>, <r v=\"1Macc.3.48\"></r>, al.): <r v=\"Rev.9.7\"></r>;</s> <s n=\"(b)\">abstract, <b>likeness</b>, <b>resemblance</b>: <r v=\"Rom.5.14\"></r> <r v=\"Rom.6.5\"></r> <r v=\"Rom.8.3\"></r>, <r v=\"Phil.2.7\"></r>; <g>ἐν ὁ. εἰκόνος</g>, <r v=\"Rom.1.23\"></r>.†</s> </s> <sy><i>SYN.</i>: <g>εἰκών</g> (q.v.), <g>ὁμοίωσις</g>.</sy>"},"G3672":{"l":"ὁμολογουμένως","o":1,"ar":"<f>** <o>ὁμολογουμένως</o>،</f> ظرف <s n=\"1.\"><b>بحسب الاتفاق</b>، <b>وفقًا لـ</b>.</s> <s n=\"2.\"><b>باعتراف الجميع</b>، <b>بالإجماع</b>: <r v=\"1Tim.3.16\"></r>.†</s>","en":"<f>** <o>ὁμολογουμένως</o>,</f> adv. <et> <e t=\"derivation\">(&lt; <g>ὁμολογέω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"4Macc.6.31\"></r> <r v=\"4Macc.7.16\"></r> <r v=\"4Macc.16.1\"></r>*;]</e> </et> <s n=\"1.\"><b>as agreed</b>, <b>conformably with</b>.</s> <s n=\"2.\"><b>confessedly</b>, <b>by common consent</b>: <r v=\"1Tim.3.16\"></r>.†</s>"},"G3644":{"l":"ὀλοθρευτής","o":1,"ar":"<f>*† <o>ὀλοθρευτής</o>، <g>-οῦ, ὁ</g></f> <s><b>المُهلِك</b>: <r v=\"1Cor.10.10\"></r> (لم ترد في غير هذا الموضع).†</s>","en":"<f>*† <o>ὀλοθρευτής</o> (Rec. <g>ὁλ-</g>), <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>ὀλοθρεύω</g>),</e> </et> <s><b>a destroyer</b>: <r v=\"1Cor.10.10\"></r> (not elsewhere).†</s>"},"G3661":{"l":"ὁμοθυμαδόν","o":11,"ar":"<f><o>ὁμοθυμαδόν</o></f> <s><b>بنفس واحدة</b>، <b>بقلب واحد</b>: <r v=\"Acts.1.14\"></r> <r v=\"Acts.2.46\"></r> <r v=\"Acts.4.24\"></r> <r v=\"Acts.5.12\"></r> <r v=\"Acts.7.57\"></r> <r v=\"Acts.8.6\"></r> <r v=\"Acts.12.20\"></r> <r v=\"Acts.15.25\"></r> <r v=\"Acts.18.12\"></r> <r v=\"Acts.19.29\"></r>، <r v=\"Rom.15.6\"></r> (ويرى بعضهم أن المعنى غير الكلاسيكي <i>معًا</i>، الوارد في <r v=\"Job.3.18\"></r> <r v=\"Job.38.33\"></r>، <r v=\"Num.24.24\"></r>، <r v=\"Wis.18.5\"></r>، <r v=\"Wis.18.12\"></r> (لكن ليس في <r v=\"Wis.10.20\"></r>)، وفي مواضع أخرى، ينبغي أن يُطبَّق على مواضع العهد الجديد، ويخالفه آخرون).†</s>","en":"<f><o>ὁμοθυμαδόν</o></f> <et> <e t=\"derivation\">(&lt; <g>ὁμός</g>, <g>θυμός</g>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H3162\">יַחַד</h> (freq. in Jb), <r v=\"Wis.10.20\"></r> <r v=\"Wis.18.5\"></r>, <r v=\"Wis.18.12\"></r>, al.;]</e> </et> <s><b>with one mind</b>, <b>with one accord</b>: <r v=\"Acts.1.14\"></r> <r v=\"Acts.2.46\"></r> <r v=\"Acts.4.24\"></r> <r v=\"Acts.5.12\"></r> <r v=\"Acts.7.57\"></r> <r v=\"Acts.8.6\"></r> <r v=\"Acts.12.20\"></r> <r v=\"Acts.15.25\"></r> <r v=\"Acts.18.12\"></r> <r v=\"Acts.19.29\"></r>, <r v=\"Rom.15.6\"></r> (Hatch, <i>Essays</i>, 63 f., argues that the un-cl. sense <i>together</i>, which is found in <r v=\"Job.3.18\"></r> <r v=\"Job.38.33\"></r>, <r v=\"Num.24.24\"></r>, <r v=\"Wis.18.5\"></r>, <r v=\"Wis.18.12\"></r> (but not <r v=\"Wis.10.20\"></r>), al., should be attached to the NT instances, but v. Abbott, <i>Essays</i>, 96; MM, xviii).†</s>"},"G3611":{"l":"οἰκέω","o":9,"ar":"<f><o>οἰκέω</o>، <g>-ῶ</g></f> <s n=\"(a)\">متعدٍّ: <b>يسكن (مكانًا)</b>: مع المنصوب، <r v=\"1Tim.6.16\"></r>؛</s> <s n=\"(b)\">لازم: <b>يسكن، يقيم</b>: يليه <g>μετά</g> (عن الحياة الزوجية)، <r v=\"1Cor.7.12\"></r>، <r v=\"1Cor.7.13\"></r>؛ مجازيًا، يليه <g>ἐν</g>: <g>ἀγαθόν</g>، <r v=\"Rom.7.18\"></r>؛ <g>ἁμαρτία</g>، <r v=\"Rom.7.20\"></r>؛ <g>πνεῦμα θεοῦ</g>، <r v=\"Rom.8.9\"></r>، <r v=\"Rom.8.11\"></r>، <r v=\"1Cor.3.16\"></r> (قارن <g>ἐν-</g>، <g>κατ-</g>، <g>ἒν-κατ-</g>، <g>παρ-</g>، <g>περι-</g>، <g>συν-οικέω</g>).†</s>","en":"<f><o>οἰκέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>οἶκος</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3427\">ישׁב</h>;]</e> </et> <s n=\"(a)\">trans., <b>to inhabit</b>: c. acc., <r v=\"1Tim.6.16\"></r>;</s> <s n=\"(b)\">intrans., <b>to dwell</b>: seq. <g>μετά</g> (of married life), <r v=\"1Cor.7.12\"></r>, <r v=\"1Cor.7.13\"></r>; metaph., seq. <g>ἐν</g>: <g>ἀγαθόν</g>, <r v=\"Rom.7.18\"></r>; <g>ἁμαρτία</g>, <r v=\"Rom.7.20\"></r>; <g>πνεῦμα θεοῦ</g>, <r v=\"Rom.8.9\"></r>, <r v=\"Rom.8.11\"></r>, <r v=\"1Cor.3.16\"></r> (cf. <g>ἐν-</g>, <g>κατ-</g>, <g>ἒν-κατ-</g>, <g>παρ-</g>, <g>περι-</g>, <g>συν-οικέω</g>).†</s>"},"G3613":{"l":"οἰκητήριον","o":2,"ar":"<f>** <o>οἰκητήριον</o>، <g>-ου, τό</g></f> <s><b>مسكن</b>: <r v=\"Jude.1.6\"></r>؛ مجازيًا، <r v=\"2Cor.5.2\"></r>.†</s>","en":"<f>** <o>οἰκητήριον</o>, <g>-ου, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>οἰκητήρ</g> = <g>οἰκήτωρ</g>, <i>an inhabitant</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"2Macc.11.2\"></r>, <r v=\"3Macc.2.15\"></r>*;]</e> </et> <s><b>a habitation</b>: <r v=\"Jude.1.6\"></r>; trop., <r v=\"2Cor.5.2\"></r>.†</s>"},"G3666":{"l":"ὁμοιόω","o":15,"ar":"<f><o>ὁμοιόω</o>، <g>-ῶ</g></f> <s n=\"1.\"><b>جعله مثل</b>، <b>شبّه</b>، مع المضاف إليه والقابل؛ المبني للمجهول: <b>صار مثل</b>، <b>أُشبِه</b>: <r v=\"Matt.6.8\"></r> <r v=\"Matt.13.24\"></r> <r v=\"Matt.18.23\"></r> <r v=\"Matt.22.2\"></r> <r v=\"Matt.25.1\"></r>، <r v=\"Acts.14.11\"></r>، <r v=\"Heb.2.17\"></r>؛ يليه <g>ὡς</g> (قارن <r v=\"Ezek.32.2\"></r>، العبرية)، <r v=\"Rom.9.29\"></r>.</s> <s n=\"2.\"><b>شبّه</b>، <b>قارن</b>: مع القابل والمنصوب، <r v=\"Matt.11.16\"></r>، <r v=\"Luke.7.31\"></r> <r v=\"Luke.13.18\"></r>، <r v=\"Luke.13.20\"></r>؛ <g>πῶς ὁμοιώσωμεν</g> (بماذا نشبّه)، <r v=\"Mark.4.30\"></r>؛ المبني للمجهول، <r v=\"Matt.7.24\"></r>، <r v=\"Matt.7.26\"></r> (قارن <g>ἀφ-ομοιόω</g>).†</s>","en":"<f><o>ὁμοιόω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>ὅμοιος</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1819\">דּמה</h>;]</e> </et> <s n=\"1.\"><b>to make like</b>, c. gen. et dat.; pass., <b>to be made</b> or <b>become like</b>: <r v=\"Matt.6.8\"></r> <r v=\"Matt.13.24\"></r> <r v=\"Matt.18.23\"></r> <r v=\"Matt.22.2\"></r> <r v=\"Matt.25.1\"></r>, <r v=\"Acts.14.11\"></r>, <r v=\"Heb.2.17\"></r>; seq. <g>ὡς</g> (cf. <r v=\"Ezek.32.2\"></r>, Heb.), <r v=\"Rom.9.29\"></r>.</s> <s n=\"2.\"><b>to liken</b>, <b>compare</b>: c. dat., acc., <r v=\"Matt.11.16\"></r>, <r v=\"Luke.7.31\"></r> <r v=\"Luke.13.18\"></r>, <r v=\"Luke.13.20\"></r>; <g>πῶς ὁμοιώσωμεν</g>, <r v=\"Mark.4.30\"></r>; pass., <r v=\"Matt.7.24\"></r>, <r v=\"Matt.7.26\"></r> (cf. <g>ἀφ-ομοιόω</g>).†</s>"},"G3660":{"l":"ὀμνύω","o":30,"ar":"<f><o>ὀμνύω</o></f> <s><b>حلف</b>، <b>أقسم، أكّد بقسم</b>: <r v=\"Matt.26.74\"></r>، <r v=\"Mark.14.71\"></r>، <r v=\"Heb.7.21\"></r>؛ يليه <g>εἰ</g> (انظره)، <r v=\"Heb.3.11\"></r> <r v=\"Heb.4.3\"></r>؛ مع القابل للشخص، <r v=\"Mark.6.23\"></r>؛ وكذلك مع المصدر، <r v=\"Heb.3.18\"></r>؛ يليه <g>ὅρκῳ</g>، <r v=\"Acts.2.30\"></r>؛ <g>ὀ. ὅρκον πρός</g>، مع المنصوب للشخص، <r v=\"Luke.1.73\"></r>؛ مع المنصوب (لما يُحلف به)، <r v=\"Jas.5.12\"></r>؛ يليه <g>κατά</g> مع المضاف إليه (كما في السبعينية)، <r v=\"Heb.6.13\"></r>، <r v=\"Heb.6.16\"></r>؛ يليه <g>ἐν</g> (<g>εἰς</g>)، كما في العبرية، <r v=\"Matt.5.34\"></r>، <r v=\"Matt.5.36\"></r> <r v=\"Matt.23.16\"></r>، <r v=\"Matt.23.18\"></r>، <r v=\"Matt.23.20-Matt.23.22\"></r>، <r v=\"Rev.10.6\"></r>.†</s>","en":"<f><o>ὀμνύω</o></f> <et> <e t=\"derivation\">(so Hdt. and some Att. writers) and <g>ὄμνυμι</g> (so generally in Att. prose and always in Trag.; <r v=\"Mark.14.71\"></r>, <g>-ύναι</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7650\">שׁבע</h> ni.;]</e> </et> <s><b>to swear</b>, <b>affirm by oath</b>: <r v=\"Matt.26.74\"></r>, <r v=\"Mark.14.71\"></r>, <r v=\"Heb.7.21\"></r>; seq. <g>εἰ</g> (q.v.), <r v=\"Heb.3.11\"></r> <r v=\"Heb.4.3\"></r>; c. dat. pers., <r v=\"Mark.6.23\"></r>; id. c. inf., <r v=\"Heb.3.18\"></r>; seq. <g>ὅρκῳ</g>, <r v=\"Acts.2.30\"></r>; <g>ὀ. ὅρκον πρός</g>, c. acc. pers. (cl.), <r v=\"Luke.1.73\"></r>; c. acc. (of that by which one swears; cl., v. MM, xviii), <r v=\"Jas.5.12\"></r>; seq. <g>κατά</g>, c. gen. (LXX; Bl., § 34, 1), <r v=\"Heb.6.13\"></r>, <r v=\"Heb.6.16\"></r>; seq. <g>ἐν</g> (<g>εἰς</g>), as in Heb. (Bl., § 39, 4), <r v=\"Matt.5.34\"></r>, <r v=\"Matt.5.36\"></r> <r v=\"Matt.23.16\"></r>, <r v=\"Matt.23.18\"></r>, <r v=\"Matt.23.20-Matt.23.22\"></r>, <r v=\"Rev.10.6\"></r> (Bl., § 70, 3).†</s>"},"G3695":{"l":"ὁπλίζω","o":1,"ar":"<f>** <o>ὁπλίζω</o></f> <s><b>أعدّ</b>، <b>جهّز</b>؛ عن الجنود، <b>سلّح</b>. الصيغة الوسطى، <b>تسلّح</b>؛ مجازيًا، <g>ἔννοιαν</g>: <r v=\"1Pet.4.1\"></r> (قارن <g>καθ-οπλίζω</g>).†</s>","en":"<f>** <o>ὁπλίζω</o></f> <et> <e t=\"derivation\">(&lt; <g>ὅπλον</g>),</e> <e t=\"septuagint\">[in Sm.: <r v=\"Jer.52.25\"></r>*;]</e> </et> <s><b>to make ready</b>, <b>equip</b>; of soldiers, <b>to arm</b>. Mid., <b>to arm oneself</b>; fig., <g>ἔννοιαν</g>: <r v=\"1Pet.4.1\"></r> (cf. <g>θράσος ὁ.</g>, Soph., <i>Elec.</i>, 995), (cf. <g>καθ-οπλίζω</g>).†</s>"},"G3648":{"l":"ὁλόκληρος","o":2,"ar":"<f><o>ὁλό-κληρος</o>، <g>-ον</g></f> <s><b>كامل</b>، <b>تام، سالم</b>؛ وفي العهد الجديد بالمعنى الأخلاقي (كما في <r v=\"Wis.15.3\"></r>، <r v=\"4Macc.15.17\"></r>)، <r v=\"1Thess.5.23\"></r>؛ <g>ὁ. καὶ τέλειοι</g>، <r v=\"Jas.1.4\"></r>.†</s>","en":"<f><o>ὁλό-κληρος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>ὅλος</g>, <g>κλῆρος</g>, i.e. <i>with all that has fallen by lot</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Lev.23.15\"></r>, <r v=\"Ezek.15.5\"></r> (<h n=\"H8549\">תָּמִים</h>), <r v=\"Deut.27.6\"></r>, <r v=\"Josh.9.2\"></r> (<r v=\"Josh.8.31\"></r>) (<h n=\"H8003\">שָׁלֵם</h>), <r v=\"Zech.11.16\"></r> (<h n=\"H5324\">נצב</h> ni.), <r v=\"Wis.15.3\"></r>, <r v=\"1Macc.4.47\"></r>, <r v=\"4Macc.15.17\"></r>*;]</e> </et> <s><b>complete</b>, <b>entire</b>; in NT in ethical sense (as <r v=\"Wis.15.3\"></r>, <r v=\"4Macc.15.17\"></r>), <r v=\"1Thess.5.23\"></r>; <g>ὁ. καὶ τέλειοι</g>, <r v=\"Jas.1.4\"></r>.†</s> <sy><i>SYN.</i>: <g>ὁλοτελής</g> (q.v.), <g>τέλειος</g> (Tr., <i>Syn.</i>, § xxii).</sy>"},"G3649":{"l":"ὀλολύζω","o":1,"ar":"<f><o>ὀλολύζω</o></f> <s><b>ولول، صرخ عاليًا</b>: <r v=\"Jas.5.1\"></r>.†</s>","en":"<f><o>ὀλολύζω</o></f> <et> <e t=\"derivation\">(onomatop.),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3213\">ילל</h> hi.;]</e> <e t=\"derivation\">(in Hom., of women crying to the gods in prayer or thanksgiving),</e> </et> <s><b>to cry aloud</b>: <r v=\"Jas.5.1\"></r>.†</s>"},"G3646":{"l":"ὁλοκαύτωμα","o":3,"ar":"<f>† <o>ὁλοκαύτωμα</o>، <g>-τος, τό</g></f> <s><b>محرقة كاملة</b>: <r v=\"Mark.12.33\"></r>، <r v=\"Heb.10.6\"></r>، <r v=\"Heb.10.8\"></r><i>(السبعينية)</i>.†</s>","en":"<f>† <o>ὁλοκαύτωμα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>ὅλος</g>, <g>καίω</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5930\">עֹלָה</h>;]</e> </et> <s><b>a whole burnt offering</b>: <r v=\"Mark.12.33\"></r>, <r v=\"Heb.10.6\"></r>, <r v=\"Heb.10.8\"></r><i>(LXX)</i> (cf. Kennedy, <i>Sources</i>, 113 f.).†</s> <sy><i>SYN.</i>: v.s. <g>θυσία</g>.</sy>"},"G3669":{"l":"ὁμοίωσις","o":1,"ar":"<f><o>ὁμοίωσις</o>، <g>-εως, ἡ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>تشبُّه</b>، <b>صيرورة على الشَّبَه</b>.</s> <s n=\"2.\"><b>شَبَه</b>: <r v=\"Jas.3.9\"></r><i>(السبعينية)</i>.†</s>","en":"<f><o>ὁμοίωσις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(<g>ὁμοιόω</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1823\">דְּמוּת</h>, <r v=\"Ps.58.4\"></r>, al.;]</e> </et> <s n=\"1.\"><b>a making like</b>, <b>becoming like</b> (Plat.).</s> <s n=\"2.\"><b>likeness</b>: <r v=\"Jas.3.9\"></r><i>(LXX)</i>.†</s> <sy><i>SYN.</i>: v.s. <g>ὁμοίωμα</g>, and cf. Tr., <i>Syn.</i>, § xv.</sy>"},"G3663":{"l":"ὁμοιοπαθής","o":2,"ar":"<f>** <o>ὁμοιοπαθής</o>، <g>-ές</g></f> <s><b>ذو مشاعر مماثلة</b> أو <b>طباع مماثلة</b> (تحت الآلام مثل غيره): مع القابل، <r v=\"Acts.14.15\"></r>، <r v=\"Jas.5.17\"></r>.†</s>","en":"<f>** <o>ὁμοιοπαθής</o>, <g>-ές</g></f> <et> <e t=\"derivation\">(&lt; <g>ὅμοιος</g>, <g>πάσχω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Wis.7.3\"></r>, <r v=\"4Macc.12.13\"></r>*;]</e> </et> <s><b>of like feelings</b> or <b>affections</b>: c. dat., <r v=\"Acts.14.15\"></r>, <r v=\"Jas.5.17\"></r>.†</s>"},"G3692":{"l":"ὀπή","o":2,"ar":"<f><o>ὀπή</o>، <g>-ῆς, ἡ</g>،</f> <s><b>فتحة</b>، <b>ثقب</b>: <r v=\"Jas.3.11\"></r> (قارن <r v=\"Exod.33.22\"></r>)، <r v=\"Heb.11.33\"></r> (قارن <r v=\"Obad.1.3\"></r>).†</s>","en":"<f><o>ὀπή</o>, <g>-ῆς, ἡ</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H2356\">חֹר</h>, <h n=\"????\">חָגוּ</h>, etc.;]</e> </et> <s><b>an opening</b>, <b>a hole</b>: <r v=\"Jas.3.11\"></r> (cf. <r v=\"Exod.33.22\"></r>), <r v=\"Heb.11.33\"></r> (cf. <r v=\"Obad.1.3\"></r>).†</s>"},"G3675":{"l":"ὁμόφρων","o":1,"ar":"<f>* <o>ὁμόφρων</o>، <g>-ον</g></f> <s><b>متّفق الرأي</b>، <b>ذو فكر واحد</b>: <r v=\"1Pet.3.8\"></r>.†</s>","en":"<f>* <o>ὁμόφρων</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>ὁμός</g>, <g>φρήν</g>), = <g>ὁμόνοος</g>,</e> </et> <s><b>agreeing</b>, <b>of one mind</b>: <r v=\"1Pet.3.8\"></r>.†</s>"},"G3693":{"l":"ὄπισθεν","o":7,"ar":"<f><o>ὄπισθεν</o>،</f> ظرف مكان، <s><b>من خلف</b>، <b>وراء</b>: <r v=\"Matt.9.20\"></r>، <r v=\"Mark.5.27\"></r>، <r v=\"Luke.8.44\"></r>، <r v=\"Rev.4.6\"></r>، <r v=\"Rev.5.1\"></r>. وكحرف جر مع المضاف إليه: <r v=\"Matt.15.23\"></r>، <r v=\"Luke.23.26\"></r>، <r v=\"Rev.1.10\"></r>.†</s>","en":"<f><o>ὄπισθεν</o>,</f> adv. of place, <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H310\">אַחַר</h>, <h n=\"H310\">מֵאַחַר</h>;]</e> </et> <s><b>behind</b>, <b>after</b>: <r v=\"Matt.9.20\"></r>, <r v=\"Mark.5.27\"></r>, <r v=\"Luke.8.44\"></r>, <r v=\"Rev.4.6\"></r> <r v=\"Rev.5.1\"></r>. As prep. c. gen.: <r v=\"Matt.15.23\"></r>, <r v=\"Luke.23.26\"></r>, <r v=\"Rev.1.10\"></r> (WH, mg.).†</s>"},"G3643":{"l":"ὀλιγωρέω","o":1,"ar":"<f><o>ὀλιγωρέω</o>، <g>-ῶ</g></f> <s><b>استخفّ</b>، <b>احتقر</b>: مع المضاف إليه، <r v=\"Heb.12.5\"></r><i>(السبعينية)</i>.†</s>","en":"<f><o>ὀλιγωρέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>ὀλίγος</g> + <g>ὤρα</g>, <i>care</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Prov.3.11\"></r> (<h n=\"H3988\">מאס</h>)*;]</e> </et> <s><b>to esteem lightly</b>, <b>think little of</b>: c. gen., <r v=\"Heb.12.5\"></r><i>(LXX)</i>.†</s>"},"G3665":{"l":"ὁμοιότης","o":2,"ar":"<f><o>ὁμοιότης</o>، <g>-ητος, ἡ</g></f> <s><b>شَبَه</b>: <g>καθ’ ὁμοιότητα</g>، <b>على نحو مماثل</b>، <r v=\"Heb.4.15\"></r>؛ وكذلك مع المضاف إليه: <b>على شبه</b> (شيء)، <r v=\"Heb.7.15\"></r>.†</s>","en":"<f><o>ὁμοιότης</o>, <g>-ητος, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>ὅμοιος</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Gen.1.11\"></r>, <r v=\"Gen.1.12\"></r> (<h n=\"H4327\">מִין</h>), <r v=\"Wis.14.19\"></r>, <r v=\"4Macc.15.4\"></r>*;]</e> </et> <s><b>likeness</b>: <g>καθ’ ὁμοιότητα</g>, <b>in like manner</b>, <r v=\"Heb.4.15\"></r>; id. c. gen. (MM, xviii), <b>after the likeness</b> (of), <r v=\"Heb.7.15\"></r>.†</s>"},"G3629":{"l":"οἰκτίρμων","o":3,"ar":"<f><o>οἰκτίρμων</o>، <g>-ον</g></f> <s><b>رحيم، رؤوف</b>: <r v=\"Luke.6.36\"></r>، <r v=\"Jas.5.1\"></r>.†</s>","en":"<f><o>οἰκτίρμων</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>οἰκτείρω</g>), in cl. poët, for <g>ἐλεήμων</g> (q.v.),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7349\">רַחוּם</h>;]</e> </et> <s><b>merciful</b>: <r v=\"Luke.6.36\"></r>, <r v=\"Jas.5.1\"></r>.†</s>"},"G3645":{"l":"ὀλοθρεύω","o":1,"ar":"<f>† <o>ὀλοθρεύω</o></f> <s><b>أهلك</b>: <r v=\"Heb.11.28\"></r> (قارن <g>ἐξ-ολοθρεύω</g>).†</s>","en":"<f>† <o>ὀλοθρεύω</o></f> <et> <e t=\"derivation\">(&lt; <g>ὄλεθρος</g>), late (Alex.) form of <g>ὄλεθρεύω</g> (cf. MGr., <g>ξολοθρεύω</g>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H3772\">כּרת</h>, <h n=\"H7843\">שׁחת</h> hi., etc.;]</e> </et> <s><b>to destroy</b>: <r v=\"Heb.11.28\"></r> (cf. <g>ἐξ-ολοθρεύω</g>).†</s>"},"G3606":{"l":"ὅθεν","o":15,"ar":"<f><o>ὅθεν </o></f> ظرف، <s><b>من حيث، من أين</b>؛ <s n=\"(a)\">عن الاتجاه أو المصدر: <r v=\"Matt.12.44\"></r>، <r v=\"Luke.11.24\"></r>، <r v=\"Acts.14.26\"></r>، <r v=\"Acts.28.13\"></r>؛ = <g>ἐκεῖθεν ὅπου</g>، <r v=\"Matt.25.24\"></r>، <r v=\"Matt.25.26\"></r>؛ <g>ὅ. γινώσκομεν</g>، <r v=\"1John.2.18\"></r>؛</s> <s n=\"(b)\">عن السبب، <b>من ثَمَّ</b>، <b>لذلك</b>: <r v=\"Matt.14.7\"></r>، <r v=\"Acts.26.19\"></r>، <r v=\"Heb.2.17\"></r>، <r v=\"Heb.3.1\"></r>، <r v=\"Heb.7.25\"></r>، <r v=\"Heb.8.3\"></r>، <r v=\"Heb.9.18\"></r>، <r v=\"Heb.11.19\"></r>.†</s> </s>","en":"<f><o>ὅθεν </o></f> adv., <s><b>whence</b>; <s n=\"(a)\">of direction or source: <r v=\"Matt.12.44\"></r>, <r v=\"Luke.11.24\"></r>, <r v=\"Acts.14.26\"></r> <r v=\"Acts.28.13\"></r>; = <g>ἐκεῖθεν ὅπου</g>, <r v=\"Matt.25.24\"></r>, <r v=\"Matt.25.26\"></r> (cf. Thuc., i, 89, 3); <g>ὅ. γινώσκομεν</g>, <r v=\"1John.2.18\"></r>;</s> <s n=\"(b)\">of cause, <b>whence</b>, <b>wherefore</b>: <r v=\"Matt.14.7\"></r>, <r v=\"Acts.26.19\"></r>, <r v=\"Heb.2.17\"></r> <r v=\"Heb.3.1\"></r> <r v=\"Heb.7.25\"></r> <r v=\"Heb.8.3\"></r> <r v=\"Heb.9.18\"></r> <r v=\"Heb.11.19\"></r>.†</s> </s>"},"G3653":{"l":"ὄλυνθος","o":1,"ar":"<f><o>ὄλυνθος</o>، <g>-ου, ὁ</g>،</f> <s><b>تين فجّ</b>، ينمو في الشتاء ويسقط عادةً في الربيع: <r v=\"Rev.6.13\"></r>.†</s>","en":"<f><o>ὄλυνθος</o>, <g>-ου, ὁ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Song.2.13\"></r> (<h n=\"H6291\">פַּגָּה</h>)*;]</e> </et> <s><b>an unripe fig</b>, which grows in winter and usually falls off in the spring: <r v=\"Rev.6.13\"></r>.†</s>"},"G3638":{"l":"ὀκτώ","o":8,"ar":"<f><o>ὀκτώ</o>، <g>οἱ, αἱ, τά</g>،</f> <s>لا يُصرَّف، <b>ثمانية</b>: <r v=\"Luke.2.21\"></r>، <r v=\"John.5.5\"></r>، وفي مواضع أخرى.</s>","en":"<f><o>ὀκτώ</o>, <g>οἱ, αἱ, τά</g>,</f> <s>indecl., <b>eight</b>: <r v=\"Luke.2.21\"></r>, <r v=\"John.5.5\"></r>, al.</s>"},"G3632":{"l":"οἰνοφλυγία","o":1,"ar":"<f>* <o>οἰνοφλυγία</o>، <g>-ας, ἡ</g></f> <s><b>إدمان الخمر</b>، <b>سُكْر، فجور</b>: <r v=\"1Pet.4.3\"></r>.†</s>","en":"<f>* <o>οἰνοφλυγία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>φλύω</g>, <i>to bubble up</i>, <i>overflow</i>), cf. <g>-γέω</g>, <r v=\"Deut.21.20\"></r>;</e> </et> <s><b>drunkenness</b>, <b>debauchery</b>: <r v=\"1Pet.4.3\"></r>.†</s> <sy><i>SYN.</i>: v.s. <g>κραιπάλη</g>.</sy>"},"G3608":{"l":"ὀθόνιον","o":5,"ar":"<f><o>ὀθόνιον</o>، <g>-ου, τό</g></f> <s><b>قطعة من الكتان الناعم</b>، <b>لفافة كتان</b>؛ <r v=\"Luke.24.12\"></r>، <r v=\"John.19.40\"></r>، <r v=\"John.20.5\"></r>، <r v=\"John.19.6\"></r>، <r v=\"John.19.7\"></r>.†</s>","en":"<f><o>ὀθόνιον</o>, <g>-ου, τό</g></f> <et> <e t=\"derivation\">(dimin. of <g>ὀθόνη</g>, q.v.),</e> <e t=\"septuagint\">[in LXX: <r v=\"Judg.14.13\"></r> (<h n=\"H5466\">סָדִין</h>), <r v=\"Hos.2.5\"></r> (<r v=\"Hos.2.7\"></r>), <r v=\"Hos.2.9\"></r> (<r v=\"Hos.2.11\"></r>) (<h n=\"H6593\">פֵּשֶׁת</h>)*;]</e> </et> <s><b>a piece of fine linen</b>, <b>a linen cloth</b>; <r v=\"Luke.24.12\"></r> (WH, R, mg., om.), <r v=\"John.19.40\"></r> <r v=\"John.20.5\"></r>, <r v=\"John.19.6\"></r>, <r v=\"John.19.7\"></r>.†</s>"},"G3647":{"l":"ὀλοκληρία","o":1,"ar":"<f>† <o>ὀλοκληρία</o>، <g>-ας, ἡ</g></f> <s><b>كمال</b>، <b>صحة تامة</b>: <r v=\"Acts.3.16\"></r>.†</s>","en":"<f>† <o>ὀλοκληρία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>ὁλόκληρος</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Isa.1.6\"></r> (<h n=\"H4974\">מְתֹם</h>)*;]</e> </et> <s><b>completeness</b>, <b>soundness</b>: <r v=\"Acts.3.16\"></r>.†</s>"},"G3678":{"l":"ὀνάριον","o":1,"ar":"<f>* <o>ὀνάριον</o>، <g>-ου, τό</g></f> <s><b>جحش</b>: <r v=\"John.12.14\"></r>.†</s>","en":"<f>* <o>ὀνάριον</o>, <g>-ου, τό</g></f> <et> <e t=\"derivation\">(dimin. of <g>ὄνος</g>),</e> </et> <s><b>a young ass</b>: <r v=\"John.12.14\"></r>.†</s>"},"G3677":{"l":"ὄναρ","o":6,"ar":"<f>* <o>ὄναρ</o>، <g>τό</g>،</f> <s>لا يُصرَّف، يُستعمل فقط في حالة الرفع والنصب المفرد (وتُستكمل الحالات الأخرى من <g>ὄνειρος</g>)، <b>حُلم</b>: <g>κατ’ ὄ.</g> (عند الكتّاب المتأخرين فقط)، <b>في حلم</b>، <r v=\"Matt.1.20\"></r> <r v=\"Matt.2.12\"></r>، <r v=\"Matt.2.13\"></r>، <r v=\"Matt.2.19\"></r>، <r v=\"Matt.2.22\"></r> <r v=\"Matt.27.19\"></r>.†</s>","en":"<f>* <o>ὄναρ</o>, <g>τό</g>,</f> <s>indecl., used only in nom, and acc. sing. (the other cases are supplied by <g>ὄνειρος</g>), <b>a dream</b>: <g>κατ’ ὄ.</g> (in later writers only), <b>in a dream</b>, <r v=\"Matt.1.20\"></r> <r v=\"Matt.2.12\"></r>, <r v=\"Matt.2.13\"></r>, <r v=\"Matt.2.19\"></r>, <r v=\"Matt.2.22\"></r> <r v=\"Matt.27.19\"></r>.†</s>"},"G3690":{"l":"ὄξος","o":6,"ar":"<f><o>ὄξος</o>، <g>-εος (-ους), τό</g></f> <s><b>خمر حامضة (خلّ)</b>، الشراب المعتاد للعمال وعامة الجنود: <r v=\"Matt.27.48\"></r>، <r v=\"Mark.15.36\"></r>، <r v=\"Luke.23.36\"></r>، <r v=\"John.19.29\"></r>، <r v=\"John.19.30\"></r>.†</s>","en":"<f><o>ὄξος</o>, <g>-εος (-ους), τό</g></f> <et> <e t=\"derivation\">(&lt; <g>ὀξύς</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Num.6.3\"></r>, <r v=\"Ruth.2.14\"></r>, <r v=\"Ps.69.21\"></r>, <r v=\"Prov.25.20\"></r> (<h n=\"H2558\">חֹמֶץ</h>)*;]</e> </et> <s><b>sour wine</b> (<l>posca</l>, <l>vin-de-pays</l>), the ordinary drink of labourers and common soldiers: <r v=\"Matt.27.48\"></r>, <r v=\"Mark.15.36\"></r>, <r v=\"Luke.23.36\"></r>, <r v=\"John.19.29\"></r>, <r v=\"John.19.30\"></r>.†</s>"},"G3688":{"l":"ὄνος","o":5,"ar":"<f><o>ὄνος</o>، <g>-ου, ὁ, ἡ</g>،</f> <s><b>حمار</b>: <r v=\"Matt.21.2\"></r>، <r v=\"Matt.21.5\"></r><i>(السبعينية)</i>، <r v=\"Luke.14.5\"></r>، <r v=\"John.12.15\"></r><i>(السبعينية)</i>؛ <g>ὁ</g>، <r v=\"Luke.13.15\"></r>؛ <g>ἡ</g>، <r v=\"Matt.21.7\"></r>.†</s>","en":"<f><o>ὄνος</o>, <g>-ου, ὁ, ἡ</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2543\">חֲמוֹר</h>, also for <h n=\"H860\">אָתוֹן</h>, etc.;]</e> </et> <s><b>an ass</b>: <r v=\"Matt.21.2\"></r>, <r v=\"Matt.21.5\"></r><i>(LXX)</i>, <r v=\"Luke.14.5\"></r>, <r v=\"John.12.15\"></r><i>(LXX)</i>; <g>ὁ</g>, <r v=\"Luke.13.15\"></r>; <g>ἡ</g>, <r v=\"Matt.21.7\"></r>.†</s>"},"G3612":{"l":"οἴκημα","o":1,"ar":"<f><o>οἴκημα</o>، <g>-τος, τό</g></f> <s><b>مسكن</b>. وكتعبير ملطَّف عن أماكن معيّنة (مثلاً <i>بيت الدعارة</i>؛ قارن <r v=\"Ezek.16.24\"></r>)، <b>سجن</b>: <r v=\"Acts.12.7\"></r>.†</s>","en":"<f><o>οἴκημα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>οἰκέω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Ezek.16.24\"></r> (<h n=\"H1354\">גַּב</h>), <r v=\"Tob.2.4\"></r>, <r v=\"Wis.13.15\"></r>*;]</e> </et> <s><b>a dwelling</b>. As a euphemism for other definite terms (e.g. <i>brothel</i>. Hdt., ii, 121; cf. <r v=\"Ezek.16.24\"></r>), <b>a prison</b> (Thuc., iv, 47 f.): <r v=\"Acts.12.7\"></r>.†</s>"},"G3674":{"l":"ὁμοῦ","o":4,"ar":"<f><o>ὁμοῦ</o>،</f> ظرف <s><b>معًا</b>؛ <s n=\"(a)\">بالمعنى الحرفي، عن المكان: <r v=\"John.21.2\"></r>، <r v=\"Acts.2.1\"></r>؛</s> <s n=\"(b)\">بدون فكرة المكان: <r v=\"John.4.36\"></r> <r v=\"John.20.4\"></r>.†</s> </s>","en":"<f><o>ὁμοῦ</o>,</f> adv. <et> <e t=\"derivation\">(&lt; <g>ὁμός</g>),</e> </et> <s><b>together</b>; <s n=\"(a)\">prop., of place: <r v=\"John.21.2\"></r>, <r v=\"Acts.2.1\"></r>;</s> <s n=\"(b)\">without idea of place: <r v=\"John.4.36\"></r> <r v=\"John.20.4\"></r>.†</s> </s>"},"G3681":{"l":"ὄνειδος","o":1,"ar":"<f><o>ὄνειδος</o>، <g>-ους, τό</g>،</f> <s n=\"1.\"><b>تعيير</b>، <b>لوم</b>، <b>ملامة</b>.</s> <s n=\"2.\"><b>ما يُعيَّر به</b>، <b>عار</b>: <r v=\"Luke.1.25\"></r>.†</s>","en":"<f><o>ὄνειδος</o>, <g>-ους, τό</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2781\">חֶרְפָּה</h>, also for <h n=\"H3639\">כְּלִמָּה</h>, etc.;]</e> </et> <s n=\"1.\"><b>reproach</b>, <b>censure</b>, <b>blame</b>.</s> <s n=\"2.\"><b>matter of reproach</b>, <b>disgrace</b>: <r v=\"Luke.1.25\"></r>.†</s>"},"G3659":{"l":"ὄμμα","o":2,"ar":"<f><o>ὄμμα</o>، <g>-τος, τό</g>، (في الكلاسيكية غالبًا شعري)؛</f> <s><b>عين</b>: في الجمع، <r v=\"Matt.20.34\"></r>، <r v=\"Mark.8.23\"></r>.†</s>","en":"<f><o>ὄμμα</o>, <g>-τος, τό</g>, in cl. chiefly poët.;</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H5869\">עַיִן</h> (Pr<i>5</i>, Wi<i>2</i>, IV Mac<i>3</i>)*;]</e> </et> <s><b>an eye</b>: pl., <r v=\"Matt.20.34\"></r>, <r v=\"Mark.8.23\"></r>.†</s>"},"G3655":{"l":"ὄμβρος","o":1,"ar":"<f><o>ὄμβρος</o>، <g>-ου, ὁ</g>،</f> <s><b>زخّة مطر</b>، <b>وابل</b>: <r v=\"Luke.12.54\"></r>.†</s>","en":"<f><o>ὄμβρος</o>, <g>-ου, ὁ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Deut.32.2\"></r> (<h n=\"H8163\">שָׂעִיר</h>), <r v=\"Wis.16.16\"></r>, al.;]</e> </et> <s><b>a storm of rain</b>, <b>a shower</b>: <r v=\"Luke.12.54\"></r>.†</s>"},"G3617":{"l":"οἰκοδεσπότης","o":12,"ar":"<f>*† <o>οἰκο-δεσπότης</o>، <g>-ου, ὁ</g></f> <s><b>ربّ البيت</b>، <b>صاحب البيت</b>: <r v=\"Matt.10.25\"></r> <r v=\"Matt.13.27\"></r> <r v=\"Matt.20.11\"></r> <r v=\"Matt.24.43\"></r>، <r v=\"Mark.14.14\"></r>، <r v=\"Luke.12.39\"></r> <r v=\"Luke.13.25\"></r> <r v=\"Luke.14.21\"></r>؛ <g>ἄνθρωπος οἰ.</g>، <r v=\"Matt.13.52\"></r> <r v=\"Matt.20.1\"></r> <r v=\"Matt.21.33\"></r>؛ بتكرار للتوكيد، <g>οἰ. τ. οἰκίας</g>، <r v=\"Luke.22.11\"></r>.†</s>","en":"<f>*† <o>οἰκο-δεσπότης</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>οἶκος</g>, <g>δεσπότης</g>),</e> </et> <s><b>the master of a house</b>, <b>a householder</b>: <r v=\"Matt.10.25\"></r> <r v=\"Matt.13.27\"></r> <r v=\"Matt.20.11\"></r> <r v=\"Matt.24.43\"></r>, <r v=\"Mark.14.14\"></r>, <r v=\"Luke.12.39\"></r> <r v=\"Luke.13.25\"></r> <r v=\"Luke.14.21\"></r>; <g>ἄνθρωπος οἰ.</g>, <r v=\"Matt.13.52\"></r> <r v=\"Matt.20.1\"></r> <r v=\"Matt.21.33\"></r>; pleonast., <g>οἰ. τ. οἰκίας</g>, <r v=\"Luke.22.11\"></r> (v. Bl., § 81, 4).†</s>"},"G3600":{"l":"ὀδυνάω","o":4,"ar":"<f><o>ὀδυνάω</o>، <g>-ῶ</g></f> <s><b>سبّب ألمًا</b> أو <b>عذابًا</b>؛ المبني للمجهول والصيغة الوسطى، <b>تألّم</b>، <b>تعذّب</b> أو <b>اغتمّ جدًا</b>: <r v=\"Luke.2.48\"></r> <r v=\"Luke.16.24\"></r>، <r v=\"Luke.16.25\"></r> (<g>ὀδυνᾶσαι</g>)؛ يليه <g>ἐπί</g>، <r v=\"Acts.20.38\"></r>.†</s>","en":"<f><o>ὀδυνάω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>ὀδύνη</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Zech.9.5\"></r> (<h n=\"H2427\">חִיל</h>), <r v=\"Zech.12.10\"></r> (<h n=\"H4843\">מרר</h> hi.), <r v=\"Lam.1.13\"></r> (<h n=\"H1739\">דָּוֶה</h>), <r v=\"Wis.14.24\"></r>, al.;]</e> </et> <s><b>to cause pain</b> or <b>suffering</b>; pass. and mid., <b>to suffer pain</b>, <b>be tormented</b> or <b>greatly distressed</b>: <r v=\"Luke.2.48\"></r> <r v=\"Luke.16.24\"></r>, <r v=\"Luke.16.25\"></r> (<g>ὀδυνᾶσαι</g>, v. M, <i>Pr.</i>, 53 f.); seq. <g>ἐπί</g>, <r v=\"Acts.20.38\"></r>.†</s>"},"G3656":{"l":"ὁμιλέω","o":4,"ar":"<f><o>ὁμιλέω</o>، <g>-ῶ</g></f> <s><b>رافق</b>، <b>عاشر</b>؛ ومن ثم <b>تحادث مع</b>: <r v=\"Acts.20.11\"></r>؛ مع القابل، <r v=\"Acts.24.26\"></r>؛ يليه <g>πρός</g>، <r v=\"Luke.24.14\"></r>، <r v=\"Luke.24.15\"></r>.†</s>","en":"<f><o>ὁμιλέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>ὅμιλος</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Prov.5.19\"></r> (<h n=\"H7301\">רוה</h> pi.), al.;]</e> </et> <s><b>to be in company with</b>, <b>consort with</b>; hence, <b>to converse with</b>: <r v=\"Acts.20.11\"></r>; c. dat., <r v=\"Acts.24.26\"></r>; seq. <g>πρός</g>, <r v=\"Luke.24.14\"></r>, <r v=\"Luke.24.15\"></r>.†</s>"},"G3607":{"l":"ὀθόνη","o":2,"ar":"<f>* <o>ὀθόνη</o>، <g>-ης, ἡ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>كتّان ناعم</b>.</s> <s n=\"2.\">لاحقًا، <b>ملاءة</b> أو <b>شراع</b>: <r v=\"Acts.10.11\"></r> <r v=\"Acts.11.5\"></r>.†</s>","en":"<f>* <o>ὀθόνη</o>, <g>-ης, ἡ</g></f> <et> <e t=\"derivation\">(of Semitic origin, cf. Heb. <h n=\"H330\">אֵטוּן</h>, <i>yarn</i>);</e> </et> <s n=\"1.\"><b>fine linen</b> (Hom., al.).</s> <s n=\"2.\">Later, <b>a sheet</b> or <b>sail</b>: <r v=\"Acts.10.11\"></r> <r v=\"Acts.11.5\"></r>.†</s>"},"G3605":{"l":"ὄζω","o":1,"ar":"<f><o>ὄζω</o>،</f> <s><b>فاحت منه رائحة</b> (أي أطلق رائحة): <r v=\"John.11.39\"></r>.†</s>","en":"<f><o>ὄζω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Exod.8.14\"></r> (<r v=\"Exod.8.10\"></r>) (<h n=\"H887\">בּאשׁ</h>)*;]</e> </et> <s><b>to smell</b> (i.e. emit a smell): <r v=\"John.11.39\"></r>.†</s>"},"G3621":{"l":"οἰκονομέω","o":1,"ar":"<f><o>οἰκονομέω</o>، <g>-ῶ</g></f> <s><b>دبّر البيت وكيلاً</b>، <b>كان وكيلاً</b>: مطلقًا، <r v=\"Luke.16.2\"></r>؛ ومن ثم عمومًا (انظر تحت مدخل <g>οἰκονομία</g>)، <b>دبّر</b>، <b>نظّم</b>، <b>رتّب</b> (<r v=\"2Macc.3.14\"></r>، <r v=\"3Macc.3.2\"></r>).†</s>","en":"<f><o>οἰκονομέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>οἰκονόμος</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Ps.112.5\"></r> (<h n=\"H3557\">כּוּל</h> pilp.), <r v=\"2Macc.3.14\"></r>*;]</e> </et> <s><b>to manage as house-steward</b>, <b>be a steward</b>: absol., <r v=\"Luke.16.2\"></r>; hence, generally (v.s. <g>οἰκονομία</g>), <b>to manage</b>, <b>regulate</b>, <b>arrange</b> (cl., <r v=\"2Macc.3.14\"></r>, <r v=\"3Macc.3.2\"></r> R).†</s>"},"G3615":{"l":"οἰκιακός","o":2,"ar":"<f>*† <o>οἰκιακός</o>، <g>ή, όν</g></f> <s><b>من أهل البيت</b>، <b>من خاصّته</b>: <r v=\"Matt.10.36\"></r>؛ عكس <g>οἰκοδεσπότης</g>، <r v=\"Matt.10.25\"></r>.†</s>","en":"<f>*† <o>οἰκιακός</o> (in Plut., al., <g>-ειακός</g>), <g>ή, όν</g></f> <et> <e t=\"derivation\">(&lt; <g>οἰκία</g>), = <g>οἰκεῖος</g>,</e> </et> <s><b>belonging to the household</b>, <b>one's own</b>: <r v=\"Matt.10.36\"></r>; opp. to <g>οἰκοδεσπότης</g>, <r v=\"Matt.10.25\"></r>.†</s>"},"G3684":{"l":"ὀνικός","o":2,"ar":"<f>*† <o>ὀνικός</o>، <g>-ή, -όν</g></f> <s><b>خاصّ بالحمار</b> أو <b>للحمار</b>: <g>μύλος ὀ.</g>، <r v=\"Matt.18.6\"></r>، <r v=\"Mark.9.42\"></r>.†</s>","en":"<f>*† <o>ὀνικός</o>, <g>-ή, -όν</g></f> <et> <e t=\"derivation\">(&lt; <g>ὄνος</g>),</e> </et> <s><b>of</b> or <b>for an ass</b>: <g>μύλος ὀ.</g>, <r v=\"Matt.18.6\"></r>, <r v=\"Mark.9.42\"></r> (elsewhere only in <g>π.</g>; v. MM, xviii).†</s>"},"G3604":{"l":"Ὀζείας","o":2,"ar":"<f><o>Ὀζείας</o>، <g>-ου, ὁ</g> (بالعبرية <h n=\"H5818\">עֻזִּיָּה</h>)،</f> <s><b>عزيا</b>: <r v=\"Matt.1.8\"></r>، <r v=\"Matt.1.9\"></r>.†</s>","en":"<f><o>Ὀζείας</o> (Rec. <g>Ὀζίας</g>), <g>-ου, ὁ</g> (Heb. <h n=\"H5818\">עֻזִּיָּה</h>),</f> <s><b>Uzziah</b>: <r v=\"Matt.1.8\"></r>, <r v=\"Matt.1.9\"></r>.†</s>"},"G3630":{"l":"οἰνοπότης","o":2,"ar":"<f><o>οἰνο-πότης</o>، <g>-ου, ὁ</g></f> <s><b>شارب خمر</b>، <b>شرّيب خمر</b>: <r v=\"Matt.11.19\"></r>، <r v=\"Luke.7.34\"></r>.†</s>","en":"<f><o>οἰνο-πότης</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>οἶνος</g> + <g>πότης</g>, <i>a drinker</i>), poët. and late prose,</e> <e t=\"septuagint\">[in LXX: <r v=\"Prov.23.20\"></r> (<h n=\"H3196\">יַיִן</h> <h n=\"H5433\">סֹבֵא</h>)*;]</e> </et> <s><b>a wine-drinker</b>, <b>wine-bibber</b>: <r v=\"Matt.11.19\"></r>, <r v=\"Luke.7.34\"></r>.†</s>"},"G3673":{"l":"ὁμότεχνος","o":1,"ar":"<f>* <o>ὁμότεχνος</o>، <g>-ον</g></f> <s><b>ممارس الصنعة نفسها</b>، <b>من الحرفة نفسها</b>: <r v=\"Acts.18.3\"></r>.†</s>","en":"<f>* <o>ὁμότεχνος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>ὁμός</g>, <g>τέχνη</g>),</e> </et> <s><b>practising the same craft</b>, <b>of the same trade</b>: <r v=\"Acts.18.3\"></r>.†</s>"},"G3635":{"l":"ὀκνέω","o":1,"ar":"<f><o>ὀκνέω</o>، <g>-ῶ</g></f> <s><b>أحجم</b> عن العمل، <b>تردّد</b> في أن يفعل؛ ومن ثم، <b>تأخّر، توانى</b> مع المصدر، <r v=\"Acts.9.38\"></r> (قارن <r v=\"Num.22.16\"></r>).†</s>","en":"<f><o>ὀκνέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>ὄκνος</g>, <i>shrinking</i>, <i>hesitation</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Num.22.16\"></r> (<h n=\"H4513\">מנע</h> ni.), <r v=\"Judg.18.9\"></r> (<h n=\"H6101\">עצל</h> ni.), <r v=\"Tob.12.6\"></r>, <r v=\"Tob.12.13\"></r>, <r v=\"Jdt.12.13\"></r>, <r v=\"Sir.7.35\"></r>, <r v=\"4Macc.14.4\"></r>*;]</e> </et> <s><b>to shrink</b> from doing, <b>hesitate</b> to do (Hom., Thuc., al.); hence, <b>to delay</b> c. inf., <r v=\"Acts.9.38\"></r> (cf. <r v=\"Num.22.16\"></r>, and v. MM, xviii).†</s>"},"G3640":{"l":"ὀλιγόπιστος","o":5,"ar":"<f>*† <o>ὀλιγό-πιστος</o>، <g>-ον</g>،</f> <s><b>قليل الإيمان</b> أو <b>الثقة</b>: <r v=\"Matt.6.30\"></r>، <r v=\"Matt.8.26\"></r>، <r v=\"Matt.14.31\"></r>، <r v=\"Matt.16.8\"></r>، <r v=\"Luke.12.28\"></r>.†</s>","en":"<f>*† <o>ὀλιγό-πιστος</o>, <g>-ον</g>,</f> <s><b>of little faith</b> or <b>trust</b>: <r v=\"Matt.6.30\"></r> <r v=\"Matt.8.26\"></r> <r v=\"Matt.14.31\"></r> <r v=\"Matt.16.8\"></r>, <r v=\"Luke.12.28\"></r>.†</s>"}});A.got[36]=1})(window.ABBOTT=window.ABBOTT||{D:{},got:{}});